async function renderCRM(){const epoch=workspaceEpoch,tab=state.crmTab==='agents'?'agents':'customers',vi=window.VTA_I18N?.language==='vi';const result=await api.request(tab);const w=$('#workspace');if(epoch!==workspaceEpoch||w?.dataset.view!=='crm')return;if(!Array.isArray(result.items))throw Error('Incomplete customer response');w.innerHTML=`<div class="page"><div class="page-head"><div><h1>CRM / Customers</h1><p>${vi?'Khách hàng và đại lý dùng chung cho báo giá và booking':'Shared customer and agent records for quotes and bookings'}</p></div><button class="btn" id="crmSales">${vi?'Mở Kinh doanh':'Open Sales'}</button></div><div class="tabs"><button data-crm-tab="customers" class="${tab==='customers'?'active':''}">${vi?'Khách hàng':'Customers'}</button><button data-crm-tab="agents" class="${tab==='agents'?'active':''}">${vi?'Đại lý':'Agents'}</button></div><p class="muted">${result.items.length} ${vi?'bản ghi đang hiển thị':'listed records'}</p><div id="salesBody">${tab==='customers'?salesCustomers(result.items):salesAgents(result.items)}</div></div>`;$('#crmSales').onclick=()=>navigate('sales');$$('[data-crm-tab]').forEach(b=>b.onclick=()=>navigate('crm',{crmTab:b.dataset.crmTab}));wireSales(tab);const create=$('#newCustomer')||$('#newAgent');if(create&&!can('customer.manage'))create.disabled=true}
async function renderDocuments(){const epoch=workspaceEpoch,vi=window.VTA_I18N?.language==='vi',source=can('document.view'),booking=can('booking.view');const [docs,bookings]=await Promise.all([source?api.request('documents'):Promise.resolve({items:[]}),booking?api.request('bookings'):Promise.resolve({items:[]})]);const w=$('#workspace');if(epoch!==workspaceEpoch||w?.dataset.view!=='documents')return;if(!Array.isArray(docs.items)||!Array.isArray(bookings.items))throw Error('Incomplete document response');w.innerHTML=`<div class="page"><div class="page-head"><div><h1>${vi?'Trung tâm tài liệu':'Document Center'}</h1><p>${vi?'Tệp nguồn, tài liệu booking và các phiên bản chứng từ':'Source files, booking attachments and versioned travel documents'}</p></div>${can('document.upload')?`<button class="btn primary" id="documentsUpload">${vi?'Upload tệp nguồn':'Upload source file'}</button>`:''}</div>${source?`<section class="panel"><div class="panel-head"><h2>${vi?'Tài liệu nhà cung cấp':'Supplier source documents'}</h2><span>${docs.items.length} ${vi?'đang hiển thị':'listed'}</span></div><div class="panel-body">${docs.items.map(d=>`<article class="attention"><div style="flex:1"><strong>${esc(d.original_filename)}</strong><p>${esc(d.supplier_name||'')} · ${esc(d.document_ref)} · ${badge(d.review_status)}</p></div>${PREVIEW?`<span class="muted">${vi?'Tệp mẫu Preview':'Preview sample file'}</span>`:`<a class="btn small" target="_blank" rel="noopener" href="api/?route=documents/${Number(d.id)}/download">${vi?'Mở tệp gốc':'Open original'}</a>`}${can('document.review')?`<button class="btn small" data-shared-doc="${Number(d.id)}">${vi?'Rà soát':'Review'}</button>`:''}</article>`).join('')||`<p class="empty">${vi?'Chưa có tệp nguồn.':'No source files.'}</p>`}</div></section>`:''}${booking?`<section class="panel"><div class="panel-head"><h2>${vi?'Tài liệu theo booking':'Booking documents'}</h2><span>${bookings.items.length} ${vi?'booking đang hiển thị':'listed bookings'}</span></div><div class="rc6-document-grid">${bookings.items.map(b=>`<article class="rc6-document-card"><strong>${esc(b.booking_ref)}</strong><p>${esc(b.lead_guest_name||'')}</p><div class="actions"><button class="btn small" data-booking-files="${Number(b.id)}">${vi?'Tệp đính kèm':'Attachments'}</button>${can('travel_document.view')?`<button class="btn small" data-travel-docs="${Number(b.id)}">${vi?'Voucher & lịch trình':'Vouchers & itinerary'}</button>`:''}</div></article>`).join('')||`<p class="empty">${vi?'Chưa có booking.':'No bookings.'}</p>`}</div></section>`:''}</div>`;if($('#documentsUpload'))$('#documentsUpload').onclick=showSupplierUpload;$$('[data-shared-doc]').forEach(b=>b.onclick=async()=>{try{const suppliers=can('supplier.view')?(await api.request('suppliers')).items:[];showDocumentReview(Number(b.dataset.sharedDoc),docs.items.find(d=>Number(d.id)===Number(b.dataset.sharedDoc)),suppliers,()=>navigate('documents'))}catch(e){toast(e.message,true)}});$$('[data-booking-files]').forEach(b=>b.onclick=()=>navigate('booking',{bookingId:Number(b.dataset.bookingFiles),bookingTab:'documents'}));$$('[data-travel-docs]').forEach(b=>b.onclick=()=>showTravelDocuments(Number(b.dataset.travelDocs)))}
async function renderFinanceOverview(body){const epoch=workspaceEpoch,vi=window.VTA_I18N?.language==='vi';const ar=can('customer_ar.view'),ap=can('supplier_ap.view');const [receivables,payables]=await Promise.all([ar?api.request('finance/ar'):Promise.resolve({items:[]}),ap?api.request('finance/ap'):Promise.resolve({items:[]})]);if(epoch!==workspaceEpoch||!body.isConnected)return;function groups(rows){const sums=new Map();for(const row of rows){const currency=row.currency;if(!/^[A-Z]{3}$/.test(currency||''))throw Error('Missing balance currency');const amount=Number(row.balance);if(!Number.isFinite(amount))throw Error('Invalid balance');sums.set(currency,(sums.get(currency)||0)+Math.round(amount*100))}return [...sums].map(([currency,cents])=>`<p><strong>${esc(currency)}</strong> ${money(cents/100,currency)}</p>`).join('')||`<p>${vi?'Chưa có công nợ.':'No balances.'}</p>`}body.innerHTML=`<div class="grid2">${ar?`<section class="panel"><div class="panel-body"><h2>${vi?'Công nợ khách hàng':'Customer balances'}</h2>${groups(receivables.items)}<small>${receivables.items.length} ${vi?'bản ghi đang hiển thị':'listed records'}</small></div></section>`:''}${ap?`<section class="panel"><div class="panel-body"><h2>${vi?'Công nợ nhà cung cấp':'Supplier balances'}</h2>${groups(payables.items)}<small>${payables.items.length} ${vi?'bản ghi đang hiển thị':'listed records'}</small></div></section>`:''}</div><div class="panel"><div class="panel-body"><h2>${vi?'Kiểm soát tài chính theo booking':'Finance control by booking'}</h2><p>${vi?'Công nợ khách hàng và nhà cung cấp được nhóm riêng theo tiền tệ của các bản ghi đang hiển thị.':'Customer and supplier balances are grouped separately by currency for the listed records.'}</p><p>${vi?'Theo dõi lịch thanh toán, hóa đơn và chi phí trong từng booking theo quyền tài khoản.':'Review payment schedules, invoices and costs within each booking according to account permissions.'}</p><div class="check warn">VTA commercial/proforma documents are not Vietnamese statutory VAT e-invoices unless separately issued through an authorized e-invoice system.</div></div></div>`}
async function onGlobalSearch(e){clearTimeout(state.searchTimer);const q=e.target.value.trim();if(q.length<2){$('#searchResults').classList.remove('open');return}state.searchTimer=setTimeout(async()=>{try{const x=await api.request('search?q='+encodeURIComponent(q));const box=$('#searchResults');let html='';for(const [k,arr] of Object.entries(x.groups||{})){if(!arr?.length)continue;html+=`<div class="search-group"><h4>${esc(k)}</h4>${arr.map(r=>`<button class="search-item" data-search-type="${esc(k)}" data-search-id="${r.id||r.booking_id||''}"><strong>${esc(r.booking_ref||r.quote_ref||r.supplier_ref||r.invoice_ref||r.flight_number||r.name||r.title||'Result')}</strong><br><small class="muted">${esc(r.lead_guest_name||r.title||r.supplier_type||r.status||r.flight_date||'')}</small></button>`).join('')}</div>`}box.innerHTML=html||'<div class="empty">No results</div>';box.classList.add('open');$$('[data-search-type]',box).forEach(b=>b.onclick=()=>{const type=b.dataset.searchType,id=Number(b.dataset.searchId);box.classList.remove('open');if(type==='bookings'||type==='flights')navigate('booking',{bookingId:id});else if(type==='quotes')navigate('quote',{quoteId:id});else if(type==='suppliers')navigate('suppliers',{productTab:'suppliers'});else if(type==='finance')navigate('finance',{financeTab:'ar'})})}catch{}},250)}
function showNewMenu(){const items=[['inquiry','inquiry.manage','New Inquiry'],['customer','customer.manage','New Customer'],['agent','customer.manage','New Agent'],['supplier','supplier.create','New Supplier'],['supplier-file','document.upload','Upload Supplier Quote'],['task','task.view','New Task']].filter(x=>can(x[1]));if(!items.length)return toast('You do not have permission to create records.',true);const m=modal('Create New',`<div class="grid2">${items.map(x=>`<button class="btn block" data-new="${x[0]}">${esc(x[2])}</button>`).join('')}</div>`);$$('[data-new]',m).forEach(b=>b.onclick=()=>{closeModal();({inquiry:showInquiryForm,customer:showCustomerForm,agent:showAgentForm,supplier:showSupplierForm,'supplier-file':showSupplierUpload,task:showTaskForm})[b.dataset.new]?.()})}

async function renderControlCenter(){
 const d=await api.request('v3/control-center');if($('#workspace')?.dataset.view!=='control')return;
 $('#workspace').innerHTML=`<div class="page"><div class="page-head"><h1>Tasks, Approvals & Alerts</h1><button class="btn" id="refreshControl">Refresh</button></div><section class="panel"><div class="panel-body"><h2>My tasks</h2>${d.tasks.map(t=>`<p><strong>${esc(t.title)}</strong> · ${esc(t.due_at||'No due date')} · ${badge(t.priority)} <button class="btn" data-control-task="${t.id}">Complete</button></p>`).join('')||'<p>No open tasks assigned to you.</p>'}</div></section><section class="panel"><div class="panel-body"><h2>Quote review queue</h2><p>Review each option’s costs, manual adjustments and margin before approving the complete quote.</p>${d.quote_reviews.map(q=>`<p>${esc(q.quote_ref)} V${q.version_no} · ${esc(q.tour_name)} · ${q.option_count} options <button class="btn" data-control-quote="${q.quote_id}">Review quote</button></p>`).join('')||'<p>No draft option bundles.</p>'}</div></section><section class="panel"><div class="panel-body"><h2>Supplier invoice review</h2>${d.supplier_reviews.map(r=>`<div class="attention"><div style="flex:1"><strong>${esc(r.supplier_name)} · ${esc(r.supplier_invoice_no)}</strong><p>${esc(r.booking_ref)} · Confirmed ${money(r.confirmed_amount,r.currency)} · Invoice ${money(r.invoice_amount,r.currency)} · Variance ${money(r.variance,r.currency)}</p><p>${esc(r.reason)}</p></div><button class="btn" data-control-review="${r.id}">Approve reconciliation</button></div>`).join('')||'<p>No supplier invoices awaiting review.</p>'}</div></section><section class="panel"><div class="panel-body"><h2>Operational alerts</h2>${d.alerts.map(i=>`<p>${badge(i.severity)} ${esc(i.booking_ref)} · ${esc(i.title)} <button class="btn" data-control-booking="${i.booking_id}">Open booking</button></p>`).join('')||'<p>No open operational issues.</p>'}</div></section><div id="attributionReport"></div><div id="auditControl"></div></div>`;
 $('#refreshControl').onclick=()=>navigate('control');$$('[data-control-quote]').forEach(b=>b.onclick=()=>navigate('quote',{quoteId:Number(b.dataset.controlQuote)}));$$('[data-control-booking]').forEach(b=>b.onclick=()=>navigate('booking',{bookingId:Number(b.dataset.controlBooking)}));
 $$('[data-control-task]').forEach(b=>b.onclick=async()=>{try{await api.request(`tasks/${b.dataset.controlTask}/complete`,{method:'POST',body:{}});await renderControlCenter()}catch(e){toast(e.message,true)}});
 $$('[data-control-review]').forEach(b=>b.onclick=async()=>{if(!await confirmBox('Approve supplier invoice','Confirm the documented invoice amount and variance have been reviewed.','Approve'))return;try{await api.request(`supplier-reconciliations/${b.dataset.controlReview}/approve`,{method:'POST',body:{}});await renderControlCenter()}catch(e){toast(e.message,true)}});
 if(can('report.view')&&can('lead.view')){const r=await api.request('v3/reports/attribution');if($('#workspace')?.dataset.view!=='control')return;$('#attributionReport').innerHTML=`<section class="panel"><div class="panel-body"><h2>Campaign conversion</h2><p>${esc(r.definition)}</p><table class="table"><thead><tr><th>Campaign</th><th>Requests</th><th>Leads</th><th>Inquiries</th><th>Quotes</th><th>Bookings</th></tr></thead><tbody>${r.items.map(c=>`<tr><td>${esc(c.campaign)}</td><td>${c.requests}</td><td>${c.qualified_leads}</td><td>${c.inquiries}</td><td>${c.quotes}</td><td>${c.bookings}</td></tr>`).join('')}</tbody></table></div></section>`;}
 if(can('audit.view')){const r=await api.request('audit?page_size=30');if($('#workspace')?.dataset.view!=='control')return;$('#auditControl').innerHTML=`<section class="panel"><div class="panel-body"><h2>Recent audit events</h2>${r.items.map(a=>`<p>${esc(a.created_at)} · ${esc(a.user_name)} · ${esc(a.action_code)} · ${esc(a.entity_type)} #${a.entity_id}</p>`).join('')}</div></section>`;}
}

async function renderToday(){const x=await api.request('dashboard');const s=x.stats||{};const w=$('#workspace');if(!w||w.dataset.view!=='today')return;w.innerHTML=`<div class="page"><div class="page-head"><div><h1>TODAY</h1><p>What needs action now?</p></div><div class="actions"><button class="btn" id="refreshToday">Refresh</button></div></div><div class="kpis"><div class="kpi"><div class="label">Open Inquiries</div><div class="value">${n(s.inquiries_open)}</div><div class="sub">Sales pipeline</div></div><div class="kpi"><div class="label">Active Bookings</div><div class="value">${n(s.bookings_active)}</div><div class="sub">${n(s.bookings_risk)} at risk</div></div><div class="kpi"><div class="label">Customer AR</div><div class="value">${money(s.ar_outstanding||0,'USD')}</div><div class="sub">Outstanding</div></div><div class="kpi"><div class="label">Supplier AP</div><div class="value">${money(s.ap_outstanding||0,'VND')}</div><div class="sub">Outstanding</div></div></div><div class="grid2"><section class="panel"><div class="panel-head"><h2>Management Attention</h2><span>${badge((x.tasks||[]).filter(t=>t.priority==='CRITICAL').length+' Critical')}</span></div><div class="panel-body">${(x.tasks||[]).length?(x.tasks||[]).map(t=>`<div class="attention ${t.priority==='CRITICAL'?'critical':t.priority==='HIGH'?'high':''}"><div class="dot"></div><div style="flex:1"><strong>${esc(t.title)}</strong><div class="meta">${esc(t.entity_type)} · ${esc(t.owner_name||'')} · ${t.due_at?fdt(t.due_at):'No deadline'} · ${esc(t.due_state||'')}</div></div><button class="btn small" data-task-done="${t.id}">Done</button></div>`).join(''):`<div class="empty"><strong>All clear</strong>No urgent tasks at the moment.</div>`}</div></section><section class="panel"><div class="panel-head"><h2>Upcoming Departures</h2><button class="btn small" data-go="operations">Open Operations</button></div><div class="panel-body">${(x.departures||[]).length?(x.departures||[]).map(b=>`<div class="attention ${b.risk_level==='CRITICAL'?'critical':b.risk_level==='HIGH'?'high':''}"><div class="dot"></div><div style="flex:1"><strong>${esc(b.booking_ref)} · ${esc(b.lead_guest_name||'')}</strong><div class="meta">${fdate(b.start_date)} · ${n(b.total_guests)} guests · Readiness ${n(b.readiness_pct)}% · ${esc(b.risk_level)}</div></div><button class="btn small" data-open-booking="${b.id}">Open</button></div>`).join(''):`<div class="empty">No departures in the next 7 days.</div>`}</div></section></div></div>`;$('#refreshToday').onclick=()=>renderToday();$$('[data-task-done]').forEach(b=>b.onclick=async()=>{await api.request(`tasks/${b.dataset.taskDone}/complete`,{method:'POST',body:{}});toast('Task completed');renderToday()});$$('[data-open-booking]').forEach(b=>b.onclick=()=>navigate('booking',{bookingId:Number(b.dataset.openBooking)}));$$('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go))}

async function renderInventory(){
 const [programs,components]=await Promise.all([api.request('inventory/programs'),api.request('inventory/components')]);
 const manage=api.user.permissions.includes('product.manage');
 $('#workspace').innerHTML=`<div class="page"><div class="page-head"><div><h1>TOUR INVENTORY</h1><p>Versioned itineraries and service blueprints</p></div><div class="actions">${manage?'<button class="btn" id="newComponent">New component</button><button class="btn primary" id="newProgram">New program</button>':''}</div></div><section class="panel"><div class="panel-body">${programs.items.map(p=>`<div class="attention"><div style="flex:1"><strong>${esc(p.code)} · ${esc(p.name)}</strong></div><button class="btn" data-program="${p.id}">Versions</button>${manage?`<button class="btn primary" data-version-create="${p.id}">Create version</button>`:''}</div>`).join('')||'<p>No programs yet.</p>'}</div></section><section class="panel"><div class="panel-head"><h2>Reusable components</h2></div><div class="panel-body">${components.items.map(c=>`<p><strong>${esc(c.name)}</strong> · ${esc(c.category)} · ${esc(c.destination)}<br>${esc(c.customer_description)}</p>`).join('')||'<p>No components yet.</p>'}</div></section></div>`;
 async function saveForm(route,form){try{await api.request(route,{method:'POST',body:formObj(form)});closeModal();navigate('inventory')}catch(e){toast(e.message,true)}}
 if(manage){
 $('#newProgram').onclick=()=>{const m=modal('New tour program','<form id="programCreate"><label>Program code<input name="code" required maxlength="64"></label><label>Program name<input name="name" required maxlength="190"></label><button class="btn primary">Create program</button></form>');$('#programCreate',m).onsubmit=e=>{e.preventDefault();saveForm('inventory/programs',e.target)}};
 $('#newComponent').onclick=()=>{const m=modal('New reusable component',`<form id="componentCreate"><label>Service name (match Rate Master product name)<input name="name" required maxlength="190"></label><label>Category<select name="category">${['HOTEL','TRANSPORT','GUIDE','CRUISE','ATTRACTION','MEAL','TOUR','VISA','OTHER'].map(c=>`<option>${c}</option>`).join('')}</select></label><label>Destination<input name="destination" required maxlength="160"></label><label>Customer description<textarea name="customer_description" required maxlength="30000"></textarea></label><button class="btn primary">Save component</button></form>`);$('#componentCreate',m).onsubmit=e=>{e.preventDefault();saveForm('inventory/components',e.target)}};
 }
 $$('[data-version-create]').forEach(button=>button.onclick=()=>showInventoryVersion(button.dataset.versionCreate,components.items));
 $$('[data-program]').forEach(button=>button.onclick=async()=>{try{
 const data=await api.request(`inventory/programs/${button.dataset.program}/versions`);
 const m=modal('Program versions',data.items.map(v=>`<div class="attention"><div style="flex:1"><strong>V${v.version_no} · ${esc(v.title)}</strong> ${badge(v.status)}</div><button class="btn" data-inspect-version="${v.id}">View</button>${manage&&v.status==='DRAFT'?`<button class="btn" data-publish-version="${v.id}">Publish</button>`:''}${v.status==='PUBLISHED'?`<button class="btn primary" data-use-version="${v.id}">Use in quote</button>`:''}</div>`).join('')||'<p>Create the first version to begin.</p>','',true);
 $$('[data-publish-version]',m).forEach(b=>b.onclick=async()=>{try{await api.request(`inventory/versions/${b.dataset.publishVersion}/publish`,{method:'POST',body:{}});closeModal();navigate('inventory')}catch(e){toast(e.message,true)}});
 $$('[data-inspect-version]',m).forEach(b=>b.onclick=()=>showInventoryDetail(b.dataset.inspectVersion));
 $$('[data-use-version]',m).forEach(b=>b.onclick=()=>showProgramQuotePicker(b.dataset.useVersion));
 }catch(e){toast(e.message,true)}});
}
function showInventoryVersion(programId,components){
 if(!components.length){toast('Create reusable components before adding a blueprint.',true);return;}
 const m=modal('Create program version','<form id="versionForm"><label>Version title<input name="title" required maxlength="190"></label><div id="inventoryDays"></div><button class="btn" type="button" id="addInventoryDay">Add day</button><fieldset class="variant-row"><legend>Agent / market variant</legend><label>Agent<select name="variant_agent"><option value="">All agents</option></select></label><label>Hotel variant<select name="hotel_level"><option>3*</option><option selected>4*</option><option>5*</option></select></label><label>Variant name<input name="variant_name" value="General" required maxlength="190"></label><label>Market (leave empty for all)<input name="market" maxlength="120"></label><label>Payment terms<textarea name="payment_terms" maxlength="4000"></textarea></label></fieldset><button type="button" class="btn" id="addTourVariant">Add another variant</button><p>Saved versions preserve their day and service content. To revise, create another version.</p><button class="btn primary">Save version</button></form>','',true);
 $('#addTourVariant',m).onclick=()=>{const original=$('.variant-row',m),row=original.cloneNode(true);$('[name=variant_name]',row).value='New variant';$('#addTourVariant',m).before(row);const remove=document.createElement('button');remove.type='button';remove.className='btn';remove.textContent='Remove variant';remove.onclick=()=>row.remove();row.append(remove)};
 api.request('inventory/agents').then(r=>{$$('[name=variant_agent]',m).forEach(select=>{select.innerHTML='<option value="">All agents</option>'+r.items.map(a=>`<option value="${a.id}">${esc(a.company_name)} · ${esc(a.market||'')}</option>`).join('')})}).catch(e=>toast(e.message,true));
 const addService=container=>{const row=document.createElement('div');row.className='blueprint-row';row.innerHTML=`<label>Service<select data-service-component>${components.map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.category)}</option>`).join('')}</select></label><label>Quantity<input data-service-qty type="number" min="0.01" max="10000" step="0.01" value="1" required></label><label>Costing pax basis<select data-service-basis><option value="TOTAL_GUESTS">All guests</option><option value="PAYING_PAX">Paying guests</option><option value="ONE">One service / vehicle / group</option></select></label><button class="btn" type="button" data-remove-service>Remove service</button>`;container.append(row);$('[data-remove-service]',row).onclick=()=>row.remove()};
 const addDay=()=>{const day=document.createElement('section');day.className='day-card inventory-day';day.innerHTML='<label>Day title<input data-day-title required maxlength="190"></label><label>Full itinerary<textarea data-day-itinerary required maxlength="30000" rows="5"></textarea></label><label>Overnight<input data-day-overnight maxlength="190"></label><label>Meals<input data-day-meals maxlength="190"></label><div data-blueprint></div><button class="btn" type="button" data-add-service>Add service</button><button class="btn" type="button" data-remove-day>Remove day</button>';$('#inventoryDays',m).append(day);$('[data-add-service]',day).onclick=()=>addService($('[data-blueprint]',day));$('[data-remove-day]',day).onclick=()=>day.remove();addService($('[data-blueprint]',day))};
 $('#addInventoryDay',m).onclick=addDay;addDay();
 $('#versionForm',m).onsubmit=async event=>{event.preventDefault();const f=formObj(event.target);const days=$$('.inventory-day',m).map(d=>({title:$('[data-day-title]',d).value,itinerary:$('[data-day-itinerary]',d).value,overnight:$('[data-day-overnight]',d).value,meals:$('[data-day-meals]',d).value,services:$$('.blueprint-row',d).map(s=>({component_id:Number($('[data-service-component]',s).value),quantity:Number($('[data-service-qty]',s).value),pax_basis:$('[data-service-basis]',s).value}))}));try{await api.request(`inventory/programs/${programId}/versions`,{method:'POST',body:{title:f.title,days,variants:$$('.variant-row',m).map(r=>({name:$('[name=variant_name]',r).value,hotel_level:$('[name=hotel_level]',r).value,market:$('[name=market]',r).value,agent_id:Number($('[name=variant_agent]',r).value)||null,payment_terms:$('[name=payment_terms]',r).value}))}});closeModal();navigate('inventory')}catch(e){toast(e.message,true)}};
}
async function showInventoryDetail(version){try{
 const data=await api.request(`inventory/versions/${version}`);
 const m=modal(data.version.title,data.days.map(d=>`<h3>Day ${d.day_no}: ${esc(d.title)}</h3><p style="white-space:pre-wrap">${esc(d.itinerary)}</p><p>Overnight: ${esc(d.overnight)} · Meals: ${esc(d.meals)}</p>${d.services.map(s=>{const c=parseJson(s.component_snapshot_json,{});return `<p>${esc(c.name)} · ${esc(s.pax_basis)} × ${esc(s.quantity)}</p>`}).join('')}`).join('')+'<hr><form id="healthForm"><label>Travel date<input type="date" name="travel_date" required></label><label>Rate band pax<input type="number" name="pax" value="10" min="1" max="10000" required></label><label>Market<input name="market"></label><button class="btn">Check Product Health</button></form><div id="healthResult"></div>','',true);
 $('#healthForm',m).onsubmit=async event=>{event.preventDefault();try{const params=new URLSearchParams(formObj(event.target));const h=await api.request(`inventory/versions/${version}/health&${params}`);$('#healthResult',m).innerHTML=h.items.map(i=>`<p>Day ${esc(i.day_no)} · ${esc(i.component)}: ${badge(i.status)}</p>`).join('')}catch(e){toast(e.message,true)}};
 }catch(e){toast(e.message,true)}}
async function showProgramQuotePicker(version){try{
 const [quotes,program]=await Promise.all([api.request('quotes'),api.request(`inventory/versions/${version}`)]);
 const drafts=quotes.items.filter(q=>q.version_status==='DRAFT');
 const m=modal('Use published program',`<form id="useProgramForm"><label>Draft quote<select name="quote_id" required>${drafts.map(q=>`<option value="${q.id}">${esc(q.quote_ref)} · ${esc(q.title)}</option>`).join('')}</select></label><label>Variant<select name="variant_id"><option value="">Base itinerary</option>${program.variants.map(v=>`<option value="${v.id}">${esc(v.name)} · ${esc(v.hotel_level)}</option>`).join('')}</select></label><p>This copies the itinerary into an empty draft quote and preserves the program version used.</p><button class="btn primary">Copy to quote</button></form>`);
 $('#useProgramForm',m).onsubmit=async event=>{event.preventDefault();const f=formObj(event.target);try{const q=await api.request(`quotes/${f.quote_id}`);await api.request(`inventory/versions/${version}/use`,{method:'POST',body:{quote_version_id:q.version.id,variant_id:f.variant_id?Number(f.variant_id):null}});closeModal();navigate('quote',{quoteId:Number(f.quote_id)})}catch(e){toast(e.message,true)}};
 }catch(e){toast(e.message,true)}}

async function renderLeadHub(){
 const epoch=workspaceEpoch,focus=state.requestId;const [campaigns,forms]=await Promise.all(['campaigns','forms'].map(x=>api.request('lead-hub/'+x)));if(epoch!==workspaceEpoch||$('#workspace')?.dataset.view!=='leads')return;
 const canCampaign=can('campaign.manage');
 $('#workspace').innerHTML=`<div class="page"><div class="page-head"><div><h1>LEAD HUB</h1><p>Campaign → MQL → Sales Accepted → Customer / Inquiry</p></div><div class="actions">${canCampaign?'<button class="btn" id="newCampaign">New campaign</button><button class="btn primary" id="newLeadForm">New form</button>':''}</div></div><div data-vs1-marketing-handover></div><section class="panel"><div class="panel-head"><h2>Forms</h2></div><div class="panel-body">${forms.items.map(f=>{const url=new URL('request.html',location.href);url.searchParams.set('form',f.public_token);return `<p><strong>${esc(f.name)}</strong> · ${badge(f.status)}<br><a href="${esc(url.href)}" target="_blank" rel="noopener">Open request form</a><br><label>Embed in landing page<textarea readonly>${esc('<script src="'+new URL('embed.js',location.href).href+'" data-form="'+f.public_token+'"></script>')}</textarea></label></p>`}).join('')||'<p>No forms yet.</p>'}</div></section></div>`;
 if(canCampaign){
 $('#newCampaign').onclick=()=>{const m=modal('New campaign','<form id="campaignForm"><label>Campaign name<input name="name" required maxlength="190"></label><label>Source<select name="source"><option>FACEBOOK</option><option>INSTAGRAM</option><option>TIKTOK</option><option>GOOGLE</option><option>WEBSITE</option><option>WHATSAPP</option><option>EMAIL</option><option>REFERRAL</option><option>MANUAL</option></select></label><button class="btn primary">Create campaign</button></form>');$('#campaignForm',m).onsubmit=async event=>{event.preventDefault();try{await api.request('lead-hub/campaigns',{method:'POST',body:formObj(event.target)});closeModal();navigate('leads')}catch(e){toast(e.message,true)}}};
 $('#newLeadForm').onclick=()=>{const m=modal('New lead form',`<form id="leadForm"><label>Name<input name="name" required maxlength="190"></label><label>Campaign<select name="campaign_id" required>${campaigns.items.filter(c=>c.status==='ACTIVE').map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Landing page URL<input name="landing_url" type="url" maxlength="1000"></label><button class="btn primary">Create form</button></form>`);$('#leadForm',m).onsubmit=async event=>{event.preventDefault();try{await api.request('lead-hub/forms',{method:'POST',body:formObj(event.target)});closeModal();navigate('leads')}catch(e){toast(e.message,true)}}};
 }
 await window.mountLeadHandover($('[data-vs1-marketing-handover]'),{api,can,navigate,notify:toast,mode:'marketing',requestId:focus});
}

async function renderSalesList(){const epoch=workspaceEpoch;const tab=state.salesTab||'inquiries';const [inq,quotes,customers,agents]=await Promise.all([api.request(state.inquiryId?'inquiries?id='+Number(state.inquiryId):'inquiries'),api.request('quotes'),api.request('customers'),api.request('agents')]);const w=$('#workspace');if(epoch!==workspaceEpoch||w?.dataset.view!=='sales-list')return;w.innerHTML=`<div class="page"><div class="page-head"><div><h1>SALES</h1><p>Inquiry → Quote → Follow-up → Confirmed</p></div><div class="actions"><button class="btn primary" id="newInquiry" ${can('inquiry.manage')?'':'disabled'}>+ New Inquiry</button></div></div><div class="tabs">${['inquiries','quotes','customers','agents'].map(x=>`<button data-sales-tab="${x}" class="${tab===x?'active':''}">${x.toUpperCase()}</button>`).join('')}</div><div id="salesBody"></div></div>`;$$('[data-sales-tab]').forEach(b=>b.onclick=()=>{navigate(['customers','agents'].includes(b.dataset.salesTab)?'crm':'sales-list',['customers','agents'].includes(b.dataset.salesTab)?{crmTab:b.dataset.salesTab}:{salesTab:b.dataset.salesTab})});$('#newInquiry').onclick=showInquiryForm;const body=$('#salesBody');if(tab==='inquiries')body.innerHTML=salesInquiries(inq.items||[]);if(tab==='quotes')body.innerHTML=salesQuotes(quotes.items||[]);if(tab==='customers')body.innerHTML=salesCustomers(customers.items||[]);if(tab==='agents')body.innerHTML=salesAgents(agents.items||[]);wireSales(tab)}
function salesInquiries(items){return `<div class="panel"><div class="panel-head"><h2>Inquiries</h2><span class="muted">${items.length} records</span></div><div class="table-wrap"><table class="table responsive"><thead><tr><th>Inquiry</th><th>Customer / Market</th><th>Travel</th><th>Pax</th><th>Status</th><th>Next Action</th><th></th></tr></thead><tbody>${items.map(x=>`<tr><td data-label="Inquiry"><strong>${esc(x.inquiry_ref)}</strong><br><span class="muted">${esc(x.title||'')}</span></td><td data-label="Customer">${esc(x.lead_contact_name||'')}<br><span class="muted">${esc(x.market||'')}</span></td><td data-label="Travel">${fdate(x.start_date)} → ${fdate(x.end_date)}</td><td data-label="Pax">${n(x.total_guests)} total · ${n(x.paying_pax)} pay · ${n(x.foc)} FOC</td><td data-label="Status">${badge(x.status)}</td><td data-label="Next Action">${esc(x.next_action||'—')}<br><span class="muted">${x.next_action_due?fdt(x.next_action_due):''}</span></td><td><button class="btn small primary" data-create-quote="${x.id}" ${can('quote.create')?'':'disabled'}>Create Quote</button></td></tr>`).join('')}</tbody></table></div></div>`}
function salesQuotes(items){return `<div class="panel"><div class="panel-head"><h2>Quotations</h2><span class="muted">Quote versions stay immutable after sending</span></div><div class="table-wrap"><table class="table responsive"><thead><tr><th>Quote</th><th>Trip</th><th>Travel</th><th>Version</th><th>Selling</th><th>Status</th><th></th></tr></thead><tbody>${items.map(x=>`<tr class="clickable" data-open-quote="${x.id}"><td data-label="Quote"><strong>${esc(x.quote_ref)}</strong></td><td data-label="Trip">${esc(x.title||x.lead_contact_name||'')}</td><td data-label="Travel">${fdate(x.start_date)} → ${fdate(x.end_date)}</td><td data-label="Version">V${n(x.current_version_no)}</td><td data-label="Selling">${money(x.total_selling||0,'USD')}<br><span class="muted">${money(x.selling_per_pax||0,'USD')}/pax</span></td><td data-label="Status">${badge(x.status)}</td><td><button class="btn small">Open</button></td></tr>`).join('')}</tbody></table></div></div>`}
function salesCustomers(items){return `<div class="toolbar"><button class="btn primary" id="newCustomer">+ Customer</button></div><div class="panel"><div class="table-wrap"><table class="table responsive"><thead><tr><th>Customer</th><th>Country / Market</th><th>WhatsApp</th><th>Email</th><th>Status</th></tr></thead><tbody>${items.map(x=>`<tr><td data-label="Customer"><button class="btn small" data-customer-360="${x.id}">${esc(x.full_name)}</button><br><span class="muted">${esc(x.customer_ref||'')}</span></td><td data-label="Market">${esc(x.country||'')} · ${esc(x.market||'')}</td><td data-label="WhatsApp">${esc(x.whatsapp||'—')}</td><td data-label="Email">${esc(x.email||'—')}</td><td data-label="Status">${badge(x.status)}</td></tr>`).join('')}</tbody></table></div></div>`}
function salesAgents(items){return `<div class="toolbar"><button class="btn primary" id="newAgent">+ Agent</button></div><div class="panel"><div class="table-wrap"><table class="table responsive"><thead><tr><th>Agent</th><th>Market</th><th>Primary Contact</th><th>WhatsApp / Email</th><th>Branding</th></tr></thead><tbody>${items.map(x=>`<tr><td data-label="Agent"><strong>${esc(x.company_name)}</strong><br><span class="muted">${esc(x.agent_ref||'')}</span></td><td data-label="Market">${esc(x.country||'')} · ${esc(x.market||'')}</td><td data-label="Contact">${esc(x.primary_contact||'—')}</td><td data-label="Contact">${esc(x.whatsapp||'')}<br>${esc(x.email||'')}</td><td data-label="Branding">${badge(x.branding_mode)}</td></tr>`).join('')}</tbody></table></div></div>`}
function wireSales(tab){if(tab==='inquiries')$$('[data-create-quote]').forEach(b=>b.onclick=async()=>{if(!can('quote.create'))return;try{const x=await api.request(`inquiries/${b.dataset.createQuote}/create-quote`,{method:'POST',body:{}});navigate('quote',{quoteId:Number(x.id)})}catch(e){toast(e.message,true)}});if(tab==='quotes')$$('[data-open-quote]').forEach(r=>r.onclick=()=>navigate('quote',{quoteId:Number(r.dataset.openQuote)}));if(tab==='customers'){$('#newCustomer').onclick=showCustomerForm;$$('[data-customer-360]').forEach(b=>b.onclick=()=>navigate('customer-360',{customerId:Number(b.getAttribute('data-customer-360'))}))}if(tab==='agents')$('#newAgent').onclick=showAgentForm}

function showCustomerForm(){if(!can('customer.manage'))return toast('You do not have permission to create this record.',true);const m=modal('New Customer',`<form id="customerForm"><div class="form-grid"><div class="field span4"><label>Full Name</label><input name="full_name" required></div><div class="field span4"><label>Country</label><input name="country"></div><div class="field span4"><label>Market</label><input name="market" placeholder="India / EU / USA..."></div><div class="field"><label>WhatsApp</label><input name="whatsapp"></div><div class="field"><label>Email</label><input name="email" type="email"></div><div class="field span12"><label>Notes</label><textarea name="notes"></textarea></div></div></form>`,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="saveCustomer">Save Customer</button>`);$('#saveCustomer',m).onclick=async()=>{const f=$('#customerForm',m);if(!f.reportValidity())return;try{await api.request('customers',{method:'POST',body:formObj(f)});closeModal();toast('Customer created');navigate('crm',{crmTab:'customers'})}catch(e){toast(e.message,true)}}}
function showAgentForm(){if(!can('customer.manage'))return toast('You do not have permission to create this record.',true);const m=modal('New B2B Agent',`<form id="agentForm"><div class="form-grid"><div class="field span4"><label>Company Name</label><input name="company_name" required></div><div class="field span4"><label>Country</label><input name="country"></div><div class="field span4"><label>Market</label><input name="market"></div><div class="field span4"><label>Primary Contact</label><input name="primary_contact"></div><div class="field span4"><label>WhatsApp</label><input name="whatsapp"></div><div class="field span4"><label>Email</label><input name="email" type="email"></div><div class="field span4"><label>Currency</label><select name="currency"><option>USD</option><option>VND</option><option>EUR</option></select></div><div class="field span4"><label>Branding</label><select name="branding_mode"><option value="VTA_ONLY">VTA Only</option><option value="AGENT_VTA">Agent + VTA</option><option value="WHITE_LABEL">White Label</option></select></div><div class="field span12"><label>Payment Terms</label><textarea name="payment_terms"></textarea></div></div></form>`,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="saveAgent">Save Agent</button>`);$('#saveAgent',m).onclick=async()=>{const f=$('#agentForm',m);if(!f.reportValidity())return;try{await api.request('agents',{method:'POST',body:formObj(f)});closeModal();toast('Agent created');navigate('crm',{crmTab:'agents'})}catch(e){toast(e.message,true)}}}
function quickParseInquiry(text){const out={request_text:text,source:'WHATSAPP',priority:'NORMAL'};const pax=text.match(/(\d+)\s*(?:pax|persons?|people|adults?)(?:\s*\+\s*(\d+)\s*FOC)?/i);if(pax){out.adults=Number(pax[1]);out.foc=Number(pax[2]||0);out.total_guests=out.adults+out.foc;out.paying_pax=out.adults}const dates=text.match(/(\d{1,2})[\-\/\s](\d{1,2})(?:[\-\/\s](\d{2,4}))?\s*(?:to|\-|–)\s*(\d{1,2})[\-\/\s](\d{1,2})(?:[\-\/\s](\d{2,4}))?/i);if(dates){const year=Number(dates[3]||dates[6]||new Date().getFullYear());const y=year<100?2000+year:year;out.start_date=`${y}-${String(dates[2]).padStart(2,'0')}-${String(dates[1]).padStart(2,'0')}`;out.end_date=`${y}-${String(dates[5]).padStart(2,'0')}-${String(dates[4]).padStart(2,'0')}`}const star=text.match(/([3-5])\s*\*|([3-5])\s*star/i);if(star)out.hotel_level=(star[1]||star[2])+'★';if(/indian/i.test(text))out.meals='Indian';if(/jain/i.test(text))out.meals=(out.meals?out.meals+', ':'')+'Jain';if(/english\s*guide/i.test(text))out.guide_language='English';if(/private/i.test(text))out.transport_type='Private';return out}
function showInquiryForm(){if(!can('inquiry.manage'))return toast('You do not have permission to create this record.',true);const body=`<div class="tabs"><button class="active" data-i-mode="paste">QUICK PASTE</button><button data-i-mode="manual">MANUAL</button></div><div id="inquiryPaste"><div class="field span12"><label>Paste WhatsApp / Email request</label><textarea id="pasteInquiry" rows="9" placeholder="Hi, need Vietnam package... 10 pax + 1 FOC..."></textarea></div><button class="btn primary" id="parseInquiry" style="margin-top:12px">Extract & Review</button></div><form id="inquiryForm" class="hidden"><div class="form-grid"><div class="field span4"><label>Lead Customer / Contact</label><input name="lead_contact_name" required></div><div class="field span4"><label>WhatsApp</label><input name="lead_whatsapp"></div><div class="field span4"><label>Email</label><input name="lead_email" type="email"></div><div class="field span4"><label>Trip Title</label><input name="title" placeholder="Vietnam Discovery 8D7N"></div><div class="field span4"><label>Market</label><input name="market" placeholder="India"></div><div class="field span4"><label>Source</label><select name="source"><option>WHATSAPP</option><option>EMAIL</option><option>WEBSITE</option><option>EXISTING_AGENT</option><option>REFERRAL</option><option>OTHER</option></select></div><div class="field span3"><label>Start Date</label><input name="start_date" type="date"></div><div class="field span3"><label>End Date</label><input name="end_date" type="date"></div><div class="field span2"><label>Adults</label><input name="adults" type="number" min="0" value="0"></div><div class="field span2"><label>FOC</label><input name="foc" type="number" min="0" value="0"></div><div class="field span2"><label>Paying Pax</label><input name="paying_pax" type="number" min="0" value="0"></div><div class="field span3"><label>Hotel Level</label><input name="hotel_level"></div><div class="field span3"><label>Meals</label><input name="meals"></div><div class="field span3"><label>Transport</label><input name="transport_type"></div><div class="field span3"><label>Guide Language</label><input name="guide_language"></div><div class="field span12"><label>Destinations / Request</label><textarea name="destination_text"></textarea></div><div class="field span12"><label>Original Request</label><textarea name="request_text"></textarea></div></div></form>`;const m=modal('New Inquiry',body,`<button class="btn" data-close>Cancel</button><button class="btn primary hidden" id="saveInquiry">Create Inquiry</button>`,true);$$('[data-i-mode]',m).forEach(b=>b.onclick=()=>{state.iMode=b.dataset.iMode;$$('[data-i-mode]',m).forEach(x=>x.classList.toggle('active',x===b));$('#inquiryPaste',m).classList.toggle('hidden',state.iMode==='manual');$('#inquiryForm',m).classList.remove('hidden');$('#saveInquiry',m).classList.remove('hidden')});$('#parseInquiry',m).onclick=()=>{const txt=$('#pasteInquiry',m).value;const d=quickParseInquiry(txt);const f=$('#inquiryForm',m);for(const [k,v] of Object.entries(d)){const e=f.elements[k];if(e)e.value=v}if(!f.elements.title.value)f.elements.title.value='Vietnam Package';f.classList.remove('hidden');$('#saveInquiry',m).classList.remove('hidden');toast('Review extracted information before creating the Inquiry')};$('#saveInquiry',m).onclick=async()=>{const f=$('#inquiryForm',m);if(!f.reportValidity())return;const d=formObj(f);d.adults=n(d.adults);d.foc=n(d.foc);d.paying_pax=n(d.paying_pax);d.total_guests=d.adults+d.foc;try{await api.request('inquiries',{method:'POST',body:d});closeModal();toast('Inquiry created');state.salesTab='inquiries';navigate('sales')}catch(e){toast(e.message,true)}}}

async function renderSupplierVault(){const tab=state.productTab||'overview';const [sup,docs,rates]=await Promise.all([can('supplier.view')?api.request('suppliers'):Promise.resolve({items:[]}),can('document.view')?api.request('documents'):Promise.resolve({items:[]}),can('rate.view')?api.request('rates'):Promise.resolve({items:[]})]);const w=$('#workspace');if(!w||w.dataset.view!=='suppliers')return;w.innerHTML=`<div class="page"><div class="page-head"><div><h1>SUPPLIER VAULT & RATES</h1><p>Supplier Vault → Human Review → Approved Rate Master</p></div><div class="actions"><button class="btn" id="supplierBack">← Operations</button><button class="btn primary" id="uploadSupplierFile" ${can('document.upload')?'':'disabled'}>Upload Supplier Quote</button></div></div><div class="tabs">${['overview','inbox','rates','suppliers'].map(x=>`<button data-product-tab="${x}" class="${tab===x?'active':''}">${x==='inbox'?'SUPPLIER INBOX':x==='rates'?'RATE MASTER':x.toUpperCase()}</button>`).join('')}</div><div id="productBody"></div></div>`;$$('[data-product-tab]').forEach(b=>b.onclick=()=>{state.productTab=b.dataset.productTab;renderSupplierVault()});$('#supplierBack').onclick=()=>navigate('operations');$('#uploadSupplierFile').onclick=showSupplierUpload;const body=$('#productBody');if(tab==='overview')body.innerHTML=productOverview(sup.items||[],docs.items||[],rates.items||[]);if(tab==='inbox')body.innerHTML=productDocs(docs.items||[]);if(tab==='rates')body.innerHTML=productRates(rates.items||[]);if(tab==='suppliers')body.innerHTML=productSuppliers(sup.items||[]);wireProduct(tab,sup.items||[],docs.items||[],rates.items||[])}
function productOverview(sup,docs,rates){const wait=docs.filter(x=>['NEW','EXTRACTED','NEEDS_REVIEW'].includes(x.review_status)).length,active=rates.filter(x=>x.approval_status==='APPROVED'&&x.health==='ACTIVE').length,exp=rates.filter(x=>x.health==='EXPIRING').length,draft=rates.filter(x=>x.approval_status!=='APPROVED').length;return `<div class="kpis"><div class="kpi"><div class="label">Active Suppliers</div><div class="value">${sup.filter(x=>x.status==='ACTIVE').length}</div></div><div class="kpi"><div class="label">Files Need Review</div><div class="value">${wait}</div></div><div class="kpi"><div class="label">Approved Rates</div><div class="value">${active}</div></div><div class="kpi"><div class="label">Rate Attention</div><div class="value">${exp+draft}</div><div class="sub">Expiring / draft</div></div></div><div class="grid2"><div class="panel"><div class="panel-head"><h2>Supplier Quote Vault</h2></div><div class="panel-body"><p>Original supplier files are preserved. Structured rates remain drafts until a human approves them.</p><div class="checklist"><div class="check ok">✓ Original file retention</div><div class="check ok">✓ Rate versions and source traceability</div><div class="check ok">✓ Human approval before Costing</div></div></div></div><div class="panel"><div class="panel-head"><h2>Needs Attention</h2></div><div class="panel-body">${wait?`<div class="attention high"><div class="dot"></div><div><strong>${wait} supplier file(s) waiting review</strong><div class="meta">Open Supplier Inbox to review extraction and source details.</div></div></div>`:''}${draft?`<div class="attention high"><div class="dot"></div><div><strong>${draft} rate(s) not approved</strong><div class="meta">Draft rates cannot be used as standard matched rates.</div></div></div>`:''}${!wait&&!draft?'<div class="empty">No Product backlog.</div>':''}</div></div></div>`}
function productDocs(items){return `<div class="toolbar"><button class="btn primary" id="uploadSupplierFile2">+ Upload File</button></div><div class="panel"><div class="table-wrap"><table class="table responsive"><thead><tr><th>Document</th><th>Supplier</th><th>Type</th><th>Validity</th><th>Extraction</th><th>Status</th><th></th></tr></thead><tbody>${items.map(x=>`<tr><td data-label="Document"><strong>${esc(x.original_filename)}</strong><br><span class="muted">${esc(x.document_ref||'')}</span></td><td data-label="Supplier">${esc(x.supplier_name||'Unassigned')}</td><td data-label="Type">${badge(x.document_type)}</td><td data-label="Validity">${fdate(x.valid_from)} → ${fdate(x.valid_to)}</td><td data-label="Extraction">${badge(x.extraction_quality)}</td><td data-label="Status">${badge(x.review_status)}</td><td><button class="btn small" data-doc-review="${x.id}">Review</button></td></tr>`).join('')}</tbody></table></div></div>`}
function productRates(items){return `<div class="toolbar"><button class="btn primary" id="newRate">+ Draft Rate</button><span class="help">Only APPROVED rates are used by Smart Rate Matching.</span></div><div class="panel"><div class="table-wrap"><table class="table responsive"><thead><tr><th>Product</th><th>Supplier</th><th>Category</th><th>Validity</th><th>Rate</th><th>Source</th><th>Health</th><th></th></tr></thead><tbody>${items.map(x=>`<tr><td data-label="Product"><strong>${esc(x.product_name)}</strong><br><span class="muted">${esc(x.option_name||'')} · ${esc(x.rate_ref||'')}</span></td><td data-label="Supplier">${esc(x.supplier_name||'')}</td><td data-label="Category">${badge(x.category)}</td><td data-label="Validity">${fdate(x.valid_from)} → ${fdate(x.valid_to)}</td><td data-label="Rate"><strong>${money(x.amount||0,x.currency||'VND')}</strong><br><span class="muted">${esc(x.rate_basis||'')}</span></td><td data-label="Source">${esc(x.source_filename||x.source_document_id||'Manual')}</td><td data-label="Health">${badge(x.health||x.approval_status)}</td><td>${x.approval_status!=='APPROVED'?`<button class="btn small success" data-rate-approve="${x.id}" data-rate-ver="${x.rate_version_no||1}">Approve</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`}
function productSuppliers(items){return `<div class="toolbar"><button class="btn primary" id="newSupplier">+ Supplier</button></div><div class="panel"><div class="table-wrap"><table class="table responsive"><thead><tr><th>Supplier</th><th>Type</th><th>City</th><th>Currency</th><th>Contact</th><th>Preferred</th><th>Status</th></tr></thead><tbody>${items.map(x=>`<tr><td data-label="Supplier"><strong>${esc(x.name)}</strong><br><span class="muted">${esc(x.supplier_ref||'')}</span></td><td data-label="Type">${badge(x.supplier_type)}</td><td data-label="City">${esc(x.city||'—')}</td><td data-label="Currency">${esc(x.currency||'')}</td><td data-label="Contact">${esc(x.primary_email||x.primary_whatsapp||'—')}</td><td data-label="Preferred">${x.preferred?'✓ Preferred':'—'}</td><td data-label="Status">${badge(x.status)}</td></tr>`).join('')}</tbody></table></div></div>`}
function wireProduct(tab,suppliers,docs,rates){if(tab==='inbox'){const b=$('#uploadSupplierFile2');if(b)b.onclick=showSupplierUpload;$$('[data-doc-review]').forEach(b=>b.onclick=()=>showDocumentReview(Number(b.dataset.docReview),docs.find(x=>x.id===Number(b.dataset.docReview)),suppliers))}if(tab==='rates'){const b=$('#newRate');if(b)b.onclick=()=>showRateForm(suppliers,docs);$$('[data-rate-approve]').forEach(b=>b.onclick=async()=>{try{await api.request(`rates/${b.dataset.rateApprove}/approve`,{method:'POST',body:{version_no:Number(b.dataset.rateVer),conflict_reviewed:true}});toast('Rate approved');renderSupplierVault()}catch(e){toast(e.message,true)}})}if(tab==='suppliers')$('#newSupplier').onclick=showSupplierForm}
function showSupplierForm(){const m=modal('New Supplier',`<form id="supplierForm"><div class="form-grid"><div class="field span4"><label>Supplier Name</label><input name="name" required></div><div class="field span4"><label>Type</label><select name="supplier_type"><option>HOTEL</option><option>TRANSPORT</option><option>GUIDE</option><option>CRUISE</option><option>TOUR</option><option>ATTRACTION</option><option>RESTAURANT</option><option>VISA</option><option>OTHER</option></select></div><div class="field span4"><label>City</label><input name="city"></div><div class="field span4"><label>Currency</label><select name="currency"><option>VND</option><option>USD</option><option>EUR</option></select></div><div class="field span4"><label>Email</label><input name="primary_email" type="email"></div><div class="field span4"><label>WhatsApp</label><input name="primary_whatsapp"></div><div class="field span12"><label>Payment Terms</label><textarea name="payment_terms"></textarea></div></div></form>`,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="saveSupplier">Save Supplier</button>`);$('#saveSupplier',m).onclick=async()=>{const f=$('#supplierForm',m);if(!f.reportValidity())return;try{await api.request('suppliers',{method:'POST',body:formObj(f)});closeModal();toast('Supplier created');state.productTab='suppliers';navigate('suppliers')}catch(e){toast(e.message,true)}}}
async function showSupplierUpload(){if(!can('document.upload'))return;const fromDocuments=state.view==='documents';let suppliers=[];if(can('supplier.view')){try{suppliers=(await api.request('suppliers')).items||[]}catch(e){toast(e.message,true);return}}const m=modal('Upload Supplier Quote / Contract',`<form id="supplierUpload"><div class="form-grid"><div class="field span6"><label>Supplier</label><select name="supplier_id"><option value="">Unassigned</option>${suppliers.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field span6"><label>Document Type</label><select name="document_type"><option>CONTRACT</option><option>RATE_SHEET</option><option>PROMOTION</option><option>SPECIAL_QUOTE</option><option>SERIES_QUOTE</option><option>SUPPLEMENT</option><option>TERMS</option><option>OTHER</option></select></div><div class="field span6"><label>Valid From</label><input type="date" name="valid_from"></div><div class="field span6"><label>Valid To</label><input type="date" name="valid_to"></div><div class="field span12"><label>Supplier File</label><input type="file" name="file" accept=".pdf,.docx,.xlsx,.csv,.txt" required></div><div class="field span12"><label>Notes</label><textarea name="notes"></textarea><span class="help">AI/parser extraction never auto-approves supplier rates.</span></div></div></form>`,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="doUpload">Upload & Extract</button>`);$('#doUpload',m).onclick=async()=>{const f=$('#supplierUpload',m);if(!f.reportValidity())return;try{const data=new FormData(f);const x=await api.request('documents/upload',{method:'POST',form:data});closeModal();toast(`Uploaded ${x.document_ref||''} · extraction ${x.extraction_quality||''}`);if(fromDocuments)navigate('documents');else{state.productTab='inbox';navigate('suppliers')}}catch(e){toast(e.message,true)}}}
function showDocumentReview(id,doc,suppliers=[],onSaved){
 if(!can('document.review'))return toast('You do not have permission to review documents.',true);
 const options=[...suppliers];if(doc?.supplier_id&&!options.some(x=>Number(x.id)===Number(doc.supplier_id)))options.unshift({id:doc.supplier_id,name:doc.supplier_name||'Current supplier #'+doc.supplier_id});
 const m=modal('Review Supplier Document',`<form id="docReview"><div class="form-grid"><div class="field span12"><label>Original File</label><div class="codeish">${esc(doc?.original_filename||'Document')}<br>${esc(doc?.document_ref||'')}<br>Extraction: ${esc(doc?.extraction_quality||'')}</div></div><div class="field span6"><label>Supplier</label><select name="supplier_id" ${can('supplier.view')?'':'disabled'}><option value="">Unassigned</option>${options.map(x=>`<option value="${Number(x.id)}" ${Number(doc?.supplier_id)===Number(x.id)?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field span6"><label>Review Status</label><select name="review_status">${['NEW','EXTRACTED','NEEDS_REVIEW','APPROVED','REJECTED','ARCHIVED'].map(s=>`<option ${doc?.review_status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field span6"><label>Document Type</label><input name="document_type" value="${esc(doc?.document_type||'OTHER')}"></div><div class="field span3"><label>Valid From</label><input type="date" name="valid_from" value="${esc(doc?.valid_from||'')}"></div><div class="field span3"><label>Valid To</label><input type="date" name="valid_to" value="${esc(doc?.valid_to||'')}"></div><div class="field span12"><label>Notes</label><textarea name="notes">${esc(doc?.notes||'')}</textarea></div></div></form>`,`<button class="btn" data-close>Cancel</button>${can('document.view')&&!PREVIEW?'<button class="btn" id="openDoc">Open Original</button>':''}<button class="btn primary" id="saveDocReview">Save Review</button>`,true);
 if($('#openDoc',m))$('#openDoc',m).onclick=()=>window.open(`api/?route=${encodeURIComponent('documents/'+id+'/download')}`,'_blank','noopener');
 $('#saveDocReview',m).onclick=async()=>{try{await api.request(`documents/${id}/review`,{method:'PUT',body:formObj($('#docReview',m))});closeModal();toast('Document review saved');if(onSaved)await onSaved();else await navigate('suppliers',{productTab:'inbox'})}catch(e){toast(e.message,true)}};
}
function showRateForm(suppliers,docs){const m=modal('Create Draft Rate',`<form id="rateForm"><div class="form-grid"><div class="field span4"><label>Supplier</label><select name="supplier_id" required><option value="">Select...</option>${suppliers.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field span4"><label>Category</label><select name="category"><option>HOTEL</option><option>TRANSPORT</option><option>GUIDE</option><option>CRUISE</option><option>TOUR</option><option>ATTRACTION</option><option>MEAL</option><option>VISA</option><option>OTHER</option></select></div><div class="field span4"><label>Rate Type</label><select name="rate_type"><option>CONTRACT</option><option>PROMOTION</option><option>SPECIAL_QUOTE</option><option>SERIES</option><option>MANUAL_OVERRIDE</option></select></div><div class="field span6"><label>Product / Service</label><input name="product_name" required></div><div class="field span3"><label>Option</label><input name="option_name"></div><div class="field span3"><label>Destination</label><input name="destination"></div><div class="field span3"><label>Amount</label><input type="number" step="0.01" name="amount" required></div><div class="field span3"><label>Currency</label><select name="currency"><option>VND</option><option>USD</option></select></div><div class="field span3"><label>Rate Basis</label><select name="rate_basis"><option>PER_PAX</option><option>PER_ROOM_NIGHT</option><option>PER_VEHICLE</option><option>PER_TRANSFER</option><option>PER_DAY</option><option>PER_GUIDE_DAY</option><option>PER_CABIN</option><option>PER_GROUP</option><option>PER_SERVICE</option></select></div><div class="field span3"><label>Source Document</label><select name="source_document_id"><option value="">Manual / Legacy</option>${docs.map(x=>`<option value="${x.id}">${esc(x.original_filename)}</option>`).join('')}</select></div><div class="field span3"><label>Valid From</label><input type="date" name="valid_from"></div><div class="field span3"><label>Valid To</label><input type="date" name="valid_to"></div><div class="field span3"><label>Market</label><input name="market"></div><div class="field span3"><label>Min Pax</label><input type="number" name="min_pax"></div><div class="field span12"><label>Terms / Notes</label><textarea name="terms"></textarea></div></div></form>`,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="saveRate">Create Draft</button>`,true);$('#saveRate',m).onclick=async()=>{const f=$('#rateForm',m);if(!f.reportValidity())return;const d=formObj(f);d.supplier_id=Number(d.supplier_id);d.amount=n(d.amount);d.source_document_id=d.source_document_id?Number(d.source_document_id):null;d.min_pax=d.min_pax?n(d.min_pax):null;d.source_origin=d.source_document_id?'SUPPLIER_DOCUMENT':(d.rate_type==='MANUAL_OVERRIDE'?'MANUAL':'LEGACY');try{await api.request('rates',{method:'POST',body:d});closeModal();toast('Draft rate created — human approval still required');state.productTab='rates';navigate('suppliers')}catch(e){toast(e.message,true)}}}

async function showQuoteOptions(){try{
 const x=await api.request(`quotes/${state.quoteId}`),v=x.version;
 const data=await api.request(`quote-versions/${v.id}/options`),locked=['SENT','CONFIRMED','SUPERSEDED'].includes(v.version_status);
 const can=p=>api.user.permissions.includes(p);
 const m=modal('Quote options · '+x.quote.quote_ref,`<p>${n(v.total_guests)} guests · ${n(v.paying_pax)} paying · ${n(v.foc)} FOC · ${badge(v.version_status)}</p>${data.items.map(o=>{const p=o.snapshot.pricing;return `<section class="panel"><div class="panel-body"><h3>${esc(o.label)} · ${esc(o.hotel_level)}</h3><p>${money(p.selling_per_pax,'USD')} / paying guest · Total ${money(p.total_selling,'USD')}</p><p>Cost ${money(p.cost_total,'USD')}${p.margin_pct!==undefined?' · Margin '+n(p.margin_pct)+'%':''} · ${esc(p.pricing_mode)}</p><p>${o.snapshot.lines.length} services${o.snapshot.manual_review_required?' · Manual costs require approval':''}</p>${!locked&&can('quote.edit')?`<button class="btn" data-edit-option="${o.id}">Edit option</button>`:''}${v.version_status==='SENT'&&can('quote.confirm')?`<button class="btn primary" data-accept-option="${o.id}">Confirm this option</button>`:''}</div></section>`}).join('')||'<p>No hotel options saved yet.</p>'}<div class="actions">${locked?`<a class="btn" target="_blank" rel="noopener" href="api/index.php?route=quote-versions/${v.id}/customer-html">View / Print customer quotation</a>`:''}${!locked&&can('quote.edit')?'<button class="btn" id="newQuoteOption">Add hotel option</button>':''}${data.items.length&&!locked&&can('quote.approve')?'<button class="btn" id="approveBundle">Approve all options</button>':''}${v.version_status==='APPROVED'&&can('quote.send')?'<button class="btn primary" id="sendBundle">Issue quote snapshot</button>':''}${v.version_status==='CONFIRMED'&&can('booking.manage')?'<button class="btn primary" id="bookBundle">Create master booking</button>':''}</div><p>Sending records an immutable quote for sharing; it does not automatically send an email or WhatsApp message.</p>`,'',true);
 if($('#newQuoteOption',m))$('#newQuoteOption',m).onclick=()=>editQuoteOption(v,null);
 $$('[data-edit-option]',m).forEach(b=>b.onclick=()=>editQuoteOption(v,data.items.find(o=>String(o.id)===b.dataset.editOption)));
 if($('#approveBundle',m))$('#approveBundle',m).onclick=()=>{const a=modal('Approve pricing','<form id="approvalReason"><label>Approval rationale (including manual rates, discounts or low margin)<textarea name="reason" required maxlength="1000"></textarea></label><button class="btn primary">Approve all options</button></form>');$('#approvalReason',a).onsubmit=async event=>{event.preventDefault();try{await api.request(`quotes/${x.quote.id}/approve`,{method:'POST',body:formObj(event.target)});showQuoteOptions()}catch(e){toast(e.message,true)}}};
 if($('#sendBundle',m))$('#sendBundle',m).onclick=async()=>{try{const sent=await api.request(`quotes/${x.quote.id}/send`,{method:'POST',body:{}});toast('Immutable snapshot issued');showQuoteOptions()}catch(e){toast(e.message,true)}};
 $$('[data-accept-option]',m).forEach(b=>b.onclick=async()=>{try{await api.request(`quotes/${x.quote.id}/confirm`,{method:'POST',body:{option_id:Number(b.dataset.acceptOption)}});showQuoteOptions()}catch(e){toast(e.message,true)}});
 if($('#bookBundle',m))$('#bookBundle',m).onclick=async()=>{try{const b=await api.request(`quotes/${x.quote.id}/create-booking`,{method:'POST',body:{}});closeModal();navigate('booking',{bookingId:b.id})}catch(e){toast(e.message,true)}};
 }catch(e){toast(e.message,true)}}
async function editQuoteOption(v,option){
 const pricing=option?.snapshot.pricing||{},lines=option?option.snapshot.lines.map(l=>({...l,reason:l.manual_reason||''})):[];
 const m=modal('Cost and price hotel option',`<form id="optionForm"><label>Option label<input name="label" required maxlength="190" value="${esc(option?.label||'Comfort')}"></label><label>Hotel level<select name="hotel_level">${['3*','4*','5*'].map(x=>`<option ${x===(option?.hotel_level||'4*')?'selected':''}>${x}</option>`).join('')}</select></label><label>VND per USD<input name="fx_rate" type="number" min="0.000001" step="0.000001" value="${n(option?.snapshot.fx_rate||v.fx_rate)}" required></label><div id="optionLines"></div><button class="btn" id="optionAddRate" type="button">Add approved rate</button><button class="btn" id="optionAddManual" type="button">Add manual service</button><label>Pricing rule<select name="pricing_mode">${['MARKUP','TARGET_MARGIN','MANUAL'].map(x=>`<option ${x===(pricing.pricing_mode||'MARKUP')?'selected':''}>${x}</option>`).join('')}</select></label><label>Markup %, target margin %, or manual USD / paying guest<input name="pricing_value" type="number" min="0" step="0.01" value="${n(pricing.pricing_value??15)}" required></label><label>Round up selling price per guest (USD; 0 = cents)<input name="rounding_step" type="number" min="0" step="0.01" value="${n(pricing.rounding_step||0)}" required></label><p>Saving replaces the draft option at this hotel level and invalidates its approval.</p><button class="btn primary">Save option</button></form><div id="optionLineEditor"></div>`,'',true);
 const renderLines=()=>{
 $('#optionLines',m).innerHTML=lines.map((l,i)=>'<div class="day-card" data-option-row="'+i+'">'+['service_name','service_date','pax','qty','unit_price'].map(k=>'<label>'+rcLabel({service_name:'Service',service_date:'Date',pax:'Pax',qty:'Qty',unit_price:'Unit Price'}[k])+rcInput(k,l[k],['pax','qty','unit_price'].includes(k)?'number':k==='service_date'?'date':'text',(l.derived_transport_extra||(l.rate_version_id&&['unit_price','service_name'].includes(k)))?'disabled':'')+'</label>').join('')+'<label>Review reason'+rcInput('reason',l.reason||l.manual_reason||'')+'</label><button type="button" class="btn" data-copy-line>Duplicate</button><button type="button" class="btn" data-remove-line>Remove</button></div>').join('');
 $$('[data-option-row]',m).forEach(row=>{const i=Number(row.dataset.optionRow);$$('[data-key]',row).forEach(e=>e.oninput=()=>lines[i][e.dataset.key]=e.type==='number'?Number(e.value):e.value);$('[data-remove-line]',row).onclick=()=>{lines.splice(i,1);renderLines()};$('[data-copy-line]',row).onclick=()=>{const c={...lines[i],rate_version_id:null,rate_snapshot:null,derived_transport_extra:false,transport_usage:null,review_required:true,reason:'Copied cost; review current dates.'};lines.splice(i+1,0,c);renderLines()}});
 };renderLines();
 const review=document.createElement('div');review.innerHTML='<label><input type="checkbox" id="reviewOptionCopied"> '+rcLabel('Reviewed for current dates')+'</label><label>Review reason<input id="reviewOptionReason"></label>';$('#optionLines',m).after(review);
 $('#optionAddRate',m).onclick=()=>{
 $('#optionLineEditor',m).innerHTML=`<form id="optionRateSearch"><h3>Find approved rate</h3><label>Category<select name="category">${['HOTEL','TRANSPORT','GUIDE','CRUISE','ATTRACTION','MEAL','TOUR','VISA','OTHER'].map(c=>`<option>${c}</option>`).join('')}</select></label><label>Destination<input name="destination" required></label><label>Service date<input name="travel_date" type="date" value="${esc(v.start_date||'')}" required></label><label>Costing pax / rooms / vehicles<input name="pax" type="number" min="0.01" step="0.01" value="" placeholder="Default by charge basis"></label><label>Quantity / nights / days<input name="qty" type="number" min="0.01" step="0.01" value="1" required></label><label>Transport hours per vehicle<input name="hours" type="number" min="0" step="0.5" value="0"></label><label>Transport kilometres per vehicle<input name="km" type="number" min="0" step="0.1" value="0"></label><label>Driver overnight stays<input name="driver_nights" type="number" min="0" value="0"></label><label>Holiday service<select name="holiday"><option value="0">No</option><option value="1">Yes</option></select></label><label>Reason if costing pax differs from total guests<input name="reason" maxlength="1000"></label><button class="btn">Find rates</button></form><div id="optionRateResults"></div>`;
 $('#optionRateSearch',m).onsubmit=async event=>{event.preventDefault();const f=formObj(event.target);try{const params=new URLSearchParams({category:f.category,destination:f.destination,travel_date:f.travel_date,pax:String(v.paying_pax),market:state.quoteData?.trip?.market||'',trip_ref:state.quoteData?.trip?.trip_ref||''});const r=await api.request('v3/rate-match&'+params);$('#optionRateResults',m).innerHTML=r.items.map((rate,i)=>`<p>${esc(rate.product_name)} · ${money(rate.effective_amount,rate.currency)} · ${esc(rate.tax_basis)} ${rate.conflict?' · REVIEW REQUIRED':`<button type="button" class="btn" data-add-option-rate="${i}">Add</button>`}</p>`).join('')||'<p>No eligible rates for this date and market.</p>';$$('[data-add-option-rate]',m).forEach(b=>b.onclick=()=>{const rate=r.items[Number(b.dataset.addOptionRate)];lines.push({rate_version_id:rate.rate_version_id,service_name:rate.product_name,service_date:f.travel_date,charge_basis:rate.rate_basis,pax:f.pax!==''?Number(f.pax):(rate.rate_basis==='PER_PAX'?Number(v.paying_pax):1),qty:Number(f.qty),unit_price:rate.effective_amount,currency:rate.currency,reason:f.reason,transport_usage:rate.category==='TRANSPORT'?{vehicles:f.pax!==''?Number(f.pax):1,days:Number(f.qty),hours:Number(f.hours),km:Number(f.km),driver_nights:Number(f.driver_nights),holiday:f.holiday==='1'}:null});$('#optionLineEditor',m).innerHTML='';renderLines()})}catch(e){toast(e.message,true)}};
 };
 $('#optionAddManual',m).onclick=async()=>{try{const suppliers=await api.request('suppliers');$('#optionLineEditor',m).innerHTML=`<form id="manualOptionLine"><h3>Manual service cost</h3><label>Service name<input name="service_name" required></label><label>Supplier<select name="supplier_id">${suppliers.items.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><label>Category<select name="category">${['HOTEL','TRANSPORT','GUIDE','CRUISE','ATTRACTION','MEAL','TOUR','VISA','OTHER'].map(c=>`<option>${c}</option>`).join('')}</select></label><label>Service date<input type="date" name="service_date" value="${esc(v.start_date||'')}" required></label><label>Charge basis<select name="charge_basis"><option value="PAYING_PAX">PAYING_PAX</option><option value="TOTAL_GUESTS">TOTAL_GUESTS</option><option value="PER_ROOM_NIGHT">PER_ROOM_NIGHT</option><option value="PER_VEHICLE">PER_VEHICLE</option><option value="PER_GROUP">PER_GROUP</option><option value="PER_SERVICE">PER_SERVICE</option></select></label><label>Costing pax<input name="pax" type="number" min="0.01" step="0.01" value="${n(v.paying_pax)}" required></label><label>Quantity<input name="qty" type="number" min="0.01" step="0.01" value="1" required></label><label>Unit price<input name="unit_price" type="number" min="0" step="0.01" required></label><label>Currency<select name="currency"><option>USD</option><option>VND</option></select></label><label>Reason for manual cost<textarea name="reason" required maxlength="1000"></textarea></label><button class="btn">Add manual service</button></form>`;$('#manualOptionLine',m).elements.charge_basis.onchange=()=>{const f=$('#manualOptionLine',m);f.elements.pax.value=f.elements.charge_basis.value==='PAYING_PAX'?v.paying_pax:f.elements.charge_basis.value==='TOTAL_GUESTS'?v.total_guests:1};$('#manualOptionLine',m).onsubmit=e=>{e.preventDefault();lines.push(formObj(e.target));$('#optionLineEditor',m).innerHTML='';renderLines()}}catch(e){toast(e.message,true)}};
 $('#optionForm',m).onsubmit=async event=>{event.preventDefault();try{await api.request(`quote-versions/${v.id}/options`,{method:'POST',body:{...formObj(event.target),lines,review_copied:$('#reviewOptionCopied',m).checked,review_reason:$('#reviewOptionReason',m).value}});showQuoteOptions()}catch(e){toast(e.message,true)}};
}

async function renderQuote(){if(!state.quoteId)return navigate('sales-list',{salesTab:'quotes'});const epoch=workspaceEpoch,id=state.quoteId;const x=await api.request(`quotes/${id}`);if(epoch!==workspaceEpoch||state.quoteId!==id||$('#workspace')?.dataset.view!=='quote')return;state.quoteData=x;const q=x.quote,v=x.version,t=x.trip;if(v.costing_engine==='VS2_1')return window.mountSmartQuote($('#workspace'),{api,quoteData:x,can,navigate,modal,closeModal,toast,refresh:renderQuote});const step=state.quoteStep||'info';const w=$('#workspace');w.innerHTML=`<div class="page"><div class="record-header"><div class="record-top"><div><div class="record-ref">${esc(q.quote_ref)} · VERSION V${n(v.version_no)}</div><div class="record-title">${esc(v.tour_name||t.title)}</div><div class="record-meta"><span>${fdate(v.start_date)} → ${fdate(v.end_date)}</span><span>${n(v.total_guests)} Guests</span><span>${n(v.paying_pax)} Paying</span><span>${n(v.foc)} FOC</span><span>${esc(t.market||'')}</span></div></div><div class="record-status">${badge(v.version_status)}<button class="btn" id="quoteBack">← Sales</button></div></div></div><div class="quote-steps">${['info','schedule','cost','price','send'].map(s=>`<button data-qstep="${s}" class="${step===s?'active':''}">${s.toUpperCase()}</button>`).join('')}</div><div id="quoteBody"></div></div>`;$('#quoteBack').onclick=()=>navigate('sales',{salesTab:'quotes'});$$('[data-qstep]').forEach(b=>b.onclick=()=>{state.quoteStep=b.dataset.qstep;renderQuote()});const body=$('#quoteBody');if(can('quote.edit')&&can('quote.view_cost')&&v.version_status==='DRAFT'){const smart=document.createElement('button');smart.className='btn';smart.textContent='Enable Smart Itinerary & Costing';smart.onclick=async()=>{try{await api.request('quote-versions/'+v.id+'/smart-costing/activate',{method:'POST',body:{expected_revision:Number(v.costing_revision||0)}});await renderQuote()}catch(e){toast(e.message,true)}};body.before(smart);}if(can('quote.create')&&can('quote.edit')){const reuse=document.createElement('button');reuse.className='btn';reuse.textContent='Clone & Reuse';reuse.onclick=()=>showQuoteReuse(v);body.before(reuse);}if(api.user.permissions.includes('quote.view_cost')){const optionsButton=document.createElement('button');optionsButton.className='btn';optionsButton.textContent='3* / 4* / 5* Options';optionsButton.onclick=showQuoteOptions;body.before(optionsButton);}if(step==='info')renderQuoteInfo(body,x);if(step==='schedule')renderQuoteSchedule(body,x);if(step==='cost')renderQuoteCost(body,x);if(step==='price')renderQuotePrice(body,x);if(step==='send')renderQuoteSend(body,x)}
function renderQuoteInfo(body,x){const v=x.version;const locked=['SENT','CONFIRMED','SUPERSEDED'].includes(v.version_status);body.innerHTML=`<div class="panel"><div class="panel-head"><h2>1. Info</h2><span class="muted">Trip information flows downstream — no retyping</span></div><div class="panel-body"><form id="quoteInfo"><div class="form-grid"><div class="field span6"><label>Tour Name</label><input name="tour_name" value="${esc(v.tour_name||'')}" ${locked?'disabled':''}></div><div class="field span3"><label>Start Date</label><input type="date" name="start_date" value="${esc(v.start_date||'')}" ${locked?'disabled':''}></div><div class="field span3"><label>End Date</label><input type="date" name="end_date" value="${esc(v.end_date||'')}" ${locked?'disabled':''}></div><div class="field span2"><label>Adults</label><input type="number" name="adults" value="${n(v.adults)}" ${locked?'disabled':''}></div><div class="field span2"><label>Children</label><input type="number" name="children" value="${n(v.children)}" ${locked?'disabled':''}></div><div class="field span2"><label>Infants</label><input type="number" name="infants" value="${n(v.infants)}" ${locked?'disabled':''}></div><div class="field span2"><label>FOC</label><input type="number" name="foc" value="${n(v.foc)}" ${locked?'disabled':''}></div><div class="field span2"><label>Total Guests</label><input type="number" name="total_guests" value="${n(v.total_guests)}" ${locked?'disabled':''}></div><div class="field span2"><label>Paying Pax</label><input type="number" name="paying_pax" value="${n(v.paying_pax)}" ${locked?'disabled':''}></div><div class="field span3"><label>Hotel Level</label><input name="hotel_level" value="${esc(v.hotel_level||'')}" ${locked?'disabled':''}></div><div class="field span3"><label>Tour Type</label><input name="tour_type" value="${esc(v.tour_type||'')}" ${locked?'disabled':''}></div><div class="field span3"><label>Document language</label><select name="document_language" ${locked?'disabled':''}><option value="en">English</option><option value="vi" ${v.document_language==='vi'?'selected':''}>Vietnamese</option></select></div><div class="field span3"><label>Guide Language</label><input name="guide_language" value="${esc(v.guide_language||'')}" ${locked?'disabled':''}></div><div class="field span3"><label>Meals</label><input name="meals" value="${esc(v.meals||'')}" ${locked?'disabled':''}></div></div></form>${locked?`<div class="check warn" style="margin-top:15px">This version is ${esc(v.version_status)} and is immutable. Create a new Quote Version to revise it.</div>`:`<div class="actions" style="margin-top:16px"><button class="btn primary" id="saveQuoteInfo">Save & Continue</button></div>`}</div></div>`;if(!locked)$('#saveQuoteInfo').onclick=async()=>{const d=formObj($('#quoteInfo'));['adults','children','infants','foc','total_guests','paying_pax'].forEach(k=>d[k]=n(d[k]));try{await api.request(`quote-versions/${v.id}`,{method:'PUT',body:d});toast('Quote info saved');state.quoteStep='schedule';renderQuote()}catch(e){toast(e.message,true)}}}

function rcLabel(s){return '<span data-i18n="'+esc(s)+'">'+esc(window.VTA_I18N?.t(s)||s)+'</span>'}
function rcInput(key,value,type='text',extra=''){return '<input data-key="'+key+'" type="'+type+'" value="'+esc(value??'')+'" '+extra+'>'}
function rcDayEditor(container,days,locked,start){
 const draw=()=>{
 container.innerHTML=days.map((d,i)=>'<section class="day-card"><div class="day-head"><strong>'+rcLabel('Date')+' '+(i+1)+'</strong>'+(!locked?'<div class="actions"><button class="btn" data-op="duplicate" data-index="'+i+'">Duplicate</button><button class="btn" data-op="up" data-index="'+i+'" '+(i===0?'disabled':'')+'>Up</button><button class="btn" data-op="down" data-index="'+i+'" '+(i===days.length-1?'disabled':'')+'>Down</button><button class="btn danger" data-op="delete" data-index="'+i+'">Delete</button></div>':'')+'</div><div class="form-grid" data-day-index="'+i+'">'+['date','title','meals','description','overnight','notes'].map(k=>'<label class="field '+(k==='description'?'span12':'span6')+'">'+rcLabel({date:'Date',title:'Route / Title',description:'Detailed Description',meals:'Meals',overnight:'Overnight',notes:'Notes'}[k])+(k==='description'?'<textarea data-key="'+k+'" '+(locked?'disabled':'')+'>'+esc(d[k]||'')+'</textarea>':rcInput(k,d[k],k==='date'?'date':'text',locked?'disabled':''))+'</label>').join('')+'</div></section>').join('')||'<p>'+rcLabel('No itinerary days yet')+'</p>';
 $$('[data-day-index] [data-key]',container).forEach(e=>e.oninput=()=>{days[Number(e.closest('[data-day-index]').dataset.dayIndex)][e.dataset.key]=e.value});
 $$('[data-op]',container).forEach(b=>b.onclick=()=>{const i=Number(b.dataset.index),op=b.dataset.op;
 if(op==='duplicate'){if(days.length>=90)return toast('Maximum 90 itinerary days',true);days.splice(i+1,0,{...days[i]});}
 if(op==='delete')days.splice(i,1);
 if(op==='up'&&i>0)[days[i-1],days[i]]=[days[i],days[i-1]];
 if(op==='down'&&i<days.length-1)[days[i+1],days[i]]=[days[i],days[i+1]];
 days.forEach((d,j)=>d.day=j+1);draw();
 });
 };draw();return draw;
}
function rcCommercialFields(values,locked=false){
 return Object.entries({included_text:'Included / Bao gồm',excluded_text:'Excluded / Không bao gồm',terms_text:'Terms / Điều khoản'}).map(([key,label])=>'<label class="field">'+esc(label)+'<textarea rows="5" name="'+key+'" '+(locked?'disabled':'')+'>'+esc(values[key]||'')+'</textarea></label>').join('');
}
function rcCommercialValues(container){return Object.fromEntries(['included_text','excluded_text','terms_text'].map(key=>[key,$('[name="'+key+'"]',container).value]));}
function renderQuoteSchedule(body,x){
 const v=x.version,locked=['SENT','CONFIRMED','SUPERSEDED'].includes(v.version_status);let days=parseJson(v.schedule_json,[]).map(d=>({...d}));
 body.innerHTML='<section class="panel"><div class="panel-head"><h2>2. Schedule</h2><div class="actions">'+(!locked?'<button class="btn" id="pasteSchedule">Quick Paste</button><button class="btn" id="uploadSchedule">Upload DOCX / PDF / TXT</button><button class="btn" id="addDay">Add Day</button>':'')+'</div></div><div class="panel-body"><div id="daysWrap"></div>'+(!locked?'<button class="btn primary" id="saveSchedule">Save Schedule & Continue</button>':'')+'</div></section>';
 $('#daysWrap',body).insertAdjacentHTML('afterend','<section id="commercialSections"><h3>Included, Excluded & Terms</h3>'+rcCommercialFields(v,locked)+'</section>');
 let draw=rcDayEditor($('#daysWrap',body),days,locked,v.start_date);
 if(locked)return;
 $('#addDay',body).onclick=()=>{if(days.length>=90)return toast('Maximum 90 itinerary days',true);const d=v.start_date?new Date(v.start_date+'T12:00:00Z'):null;if(d)d.setUTCDate(d.getUTCDate()+days.length);days.push({day:days.length+1,date:d?d.toISOString().slice(0,10):'',title:'',description:'',meals:'',overnight:''});draw()};
 const imported=(updated,sections)=>{days=updated;draw=rcDayEditor($('#daysWrap',body),days,false,v.start_date);for(const [key,value] of Object.entries(sections))$('[name="'+key+'"]',body).value=value;};
 $('#pasteSchedule',body).onclick=()=>showSchedulePaste(days,{...v,...rcCommercialValues(body)},imported);
 $('#uploadSchedule',body).onclick=()=>showSchedulePaste(days,{...v,...rcCommercialValues(body)},imported,true);
 $('#saveSchedule',body).onclick=async()=>{try{await api.request('quote-versions/'+v.id,{method:'PUT',body:{schedule:days.map((d,i)=>({...d,day:i+1})),...rcCommercialValues(body)}});toast('Schedule saved');state.quoteStep='cost';await renderQuote()}catch(e){toast(e.message,true)}};
}
function showSchedulePaste(existing,v,done,upload=false){
 if(PREVIEW)return toast('Use the local or staging API for document import.',true);
 const m=modal('Import itinerary','<label>Paste day-by-day itinerary<textarea id="schedulePaste" rows="10" placeholder="Day 1: Hanoi&#10;Full description&#10;Meals: B/L&#10;Overnight: Hanoi&#10;&#10;Ngày 2: Hạ Long"></textarea></label><label>Upload DOCX / PDF / TXT<input id="scheduleFile" type="file" accept=".docx,.pdf,.txt"></label><button class="btn" id="extractDays">Extract DRAFT preview</button><div id="importPreview"></div>','<button class="btn" data-close>Cancel</button><button class="btn primary" id="applyPreview" disabled>Apply preview</button>',true);
 let preview=null,sectionsFound={};
 if(upload)$('#scheduleFile',m).focus();
 $('#extractDays',m).onclick=async()=>{const b=$('#extractDays',m);b.disabled=true;try{
 let result;const file=$('#scheduleFile',m).files[0];
 if(file){const form=new FormData();form.append('file',file);form.append('start_date',v.start_date||'');result=await api.request('schedule/preview',{method:'POST',form});}
 else result=await api.request('schedule/preview',{method:'POST',body:{text:$('#schedulePaste',m).value,start_date:v.start_date||''}});
 preview=result.days;$('#importPreview',m).innerHTML='<h2>DRAFT preview</h2><p>'+rcLabel('Review before applying. Nothing has been saved.')+'</p>'+result.warnings.map(w=>'<p>'+rcLabel(w)+'</p>').join('')+'<details><summary>'+rcLabel('Source text')+'</summary><pre style="white-space:pre-wrap" data-no-translate>'+esc(result.source_text)+'</pre></details><label><select id="importMode"><option value="append">Append days</option><option value="replace">Replace days</option></select></label><div id="previewDays"></div>';
 sectionsFound=result.sections_found||{};
 $('#importPreview',m).insertAdjacentHTML('beforeend','<section id="previewSections">'+rcCommercialFields(result)+ '</section>');
 for(const key of ['included_text','excluded_text','terms_text']){
  const field=$('[name="'+key+'"]',m),found=sectionsFound[key]===true;
  field.disabled=!found;
  field.insertAdjacentHTML('beforebegin','<select aria-label="Import action for '+key+'" data-section-mode="'+key+'" '+(!found?'disabled':'')+'><option value="keep">Keep existing / Giữ hiện tại</option>'+(found?'<option value="replace">Replace / Thay thế</option><option value="append">Append / Nối thêm</option>':'')+'</select>'+(!found?'<p>Không tìm thấy mục này trong tài liệu; giữ nội dung hiện tại.</p>':''));
  $('[data-section-mode="'+key+'"]',m).value=found&&!String(v[key]||'').trim()?'replace':'keep';
 }
 rcDayEditor($('#previewDays',m),preview,false,v.start_date);$('#applyPreview',m).disabled=false;
 }catch(e){preview=null;$('#applyPreview',m).disabled=true;toast(e.message,true)}finally{b.disabled=false}};
 $('#applyPreview',m).onclick=()=>{if(!preview)return;const updated=$('#importMode',m).value==='append'?[...existing,...preview]:preview;if(updated.length>90)return toast('Maximum 90 itinerary days',true);
 const sections={};for(const key of ['included_text','excluded_text','terms_text']){const mode=$('[data-section-mode="'+key+'"]',m).value,value=$('[name="'+key+'"]',m).value;sections[key]=v[key]||'';if(sectionsFound[key]===true&&mode!=='keep')sections[key]=mode==='append'?[sections[key],value].filter(Boolean).join('\n'):value;}
 closeModal();done(updated.map((d,i)=>({...d,day:i+1})),sections)};
}
function renderQuoteCost(body,x){
 const v=x.version,locked=['SENT','CONFIRMED','SUPERSEDED'].includes(v.version_status),items=x.cost_items||[];
 body.innerHTML='<section class="panel"><div class="panel-head"><h2>3. Cost</h2><div class="actions">'+(!locked?'<button class="btn" id="matchRate">Match Approved Rate</button><button class="btn" id="addCost">Add Cost Item</button><button class="btn" id="pasteCost">Excel Paste</button>':'')+'</div></div><div class="panel-body"><div class="table-wrap"><table class="table"><thead><tr>'+['Service','Pax','Qty','Unit Price','Total','Source','Notes'].map(s=>'<th>'+rcLabel(s)+'</th>').join('')+'<th></th></tr></thead><tbody>'+items.map(c=>'<tr data-cost="'+c.id+'"><td>'+rcInput('service_name',c.service_name,'text',locked?'disabled':'')+'<small>'+esc(c.category)+' · '+esc(c.service_date)+' · '+esc(c.currency)+'</small></td>'+['pax','qty','unit_price'].map(k=>'<td>'+rcInput(k,c[k],'number','min="'+(k==='unit_price'?'0':'0.01')+'" step="0.01" '+(locked?'disabled':''))+'</td>').join('')+'<td data-total>'+money(c.total,c.currency)+'</td><td>'+badge(c.source_type)+(Number(c.review_required)?'<p>'+rcLabel('Needs Review')+'</p>':'')+'</td><td>'+rcInput('notes',c.notes,'text',locked?'disabled':'')+(!locked&&Number(c.review_required)?'<label><input data-reviewed type="checkbox"> '+rcLabel('Reviewed for current dates')+'</label>':'')+'</td><td>'+(!locked?'<button class="btn" data-save-cost>Save row</button><button class="btn" data-duplicate-cost>Duplicate row</button><button class="btn" data-detail-cost>Edit</button><button class="btn" data-refresh-cost>Refresh rate</button><button class="btn danger" data-del-cost>Delete</button>':'')+'</td></tr>').join('')+'</tbody></table></div><div class="cost-summary"><div class="cost-box"><label>Total Cost</label><b>'+money(v.total_cost||0,v.cost_currency||'VND')+'</b></div><div class="cost-box"><label>Cost / Paying Pax</label><b>'+money(v.cost_per_paying_pax||0,'USD')+'</b></div><div class="cost-box"><label>Paying Pax</label><b>'+n(v.paying_pax)+'</b></div></div>'+(!locked?'<button class="btn primary" id="costContinue">Continue to Price</button>':'')+'</div></section>';
 if(locked)return;
 $('#addCost',body).onclick=()=>showCostForm(v);$('#matchRate',body).onclick=()=>showRateMatch(v);$('#pasteCost',body).onclick=()=>showCostPaste(v);
 $$('[data-cost]',body).forEach(row=>{const c=items.find(i=>String(i.id)===row.dataset.cost),id=c.id;
 const read=()=>Object.fromEntries($$('[data-key]',row).map(e=>[e.dataset.key,e.type==='number'?Number(e.value):e.value]));
 row.oninput=()=>{const d=read();$('[data-total]',row).textContent=money(d.pax*d.qty*d.unit_price,c.currency)};
 $('[data-save-cost]',row).onclick=async()=>{try{await api.request('cost-items/'+id,{method:'PATCH',body:{...read(),reviewed:!!$('[data-reviewed]',row)?.checked}});toast('Cost saved');await renderQuote()}catch(e){toast(e.message,true)}};
 $('[data-duplicate-cost]',row).onclick=async()=>{try{await api.request('cost-items/'+id+'/duplicate',{method:'POST',body:{}});await renderQuote()}catch(e){toast(e.message,true)}};
 $('[data-detail-cost]',row).onclick=()=>showCostForm(v,{...c,...read()});
 $('[data-refresh-cost]',row).onclick=()=>showRateMatch(v,c);
 $('[data-del-cost]',row).onclick=async()=>{if(!await confirmBox('Delete','Remove this cost item?','Delete'))return;try{await api.request('cost-items/'+id,{method:'DELETE'});await renderQuote()}catch(e){toast(e.message,true)}};
 });
 $('#costContinue',body).onclick=()=>{state.quoteStep='price';renderQuote()};
}
function showCostForm(v,preset={}){
 const basis=preset.charge_basis||preset.rate_basis||'PAYING_PAX',pax=preset.pax??(['PAYING_PAX','PER_PAX'].includes(basis)?v.paying_pax:basis==='TOTAL_GUESTS'?v.total_guests:1);
 const field=(label,key,value,type='text')=>'<label class="field span4">'+rcLabel(label)+'<input name="'+key+'" type="'+type+'" value="'+esc(value??'')+'" '+(type==='number'?'min="0" step="0.01"':'')+' required></label>';
 const m=modal('Add Cost Item','<form id="costForm"><div class="form-grid">'+field('Service','service_name',preset.service_name||preset.product_name||'')+field('Date','service_date',preset.service_date||v.start_date,'date')+'<label class="field span4">Category<select name="category">'+['TRANSPORT','GUIDE','HOTEL','MEAL','ATTRACTION','TOUR','CRUISE','VISA','OTHER'].map(s=>'<option value="'+s+'" '+(s===(preset.category||'OTHER')?'selected':'')+'>'+s+'</option>').join('')+'</select></label><label class="field span4">Charge basis<select name="charge_basis">'+['PAYING_PAX','TOTAL_GUESTS','PER_PAX','PER_ROOM_NIGHT','PER_VEHICLE','PER_TRANSFER','PER_DAY','PER_GUIDE_DAY','PER_CABIN','PER_GROUP','PER_SERVICE'].map(s=>'<option value="'+s+'" '+(s===basis?'selected':'')+'>'+s+'</option>').join('')+'</select></label>'+field('Pax','pax',pax,'number')+field('Qty','qty',preset.qty??1,'number')+field('Unit Price','unit_price',preset.effective_amount??preset.unit_price??preset.amount??0,'number')+'<label class="field span4">Currency<select name="currency"><option value="VND">VND</option><option value="USD" '+(preset.currency==='USD'?'selected':'')+'>USD</option></select></label><label class="field span12">Review reason<textarea name="notes">'+esc(preset.notes||'')+'</textarea></label>'+(preset.rate_version_id?'<label class="field span6"><input type="checkbox" name="manual"> '+rcLabel('Convert to manual')+'</label>':'')+(Number(preset.review_required)?'<label class="field span6"><input name="reviewed" type="checkbox"> '+rcLabel('Reviewed for current dates')+'</label>':'')+'</div></form>','<button class="btn" data-close>Cancel</button><button class="btn primary" id="saveCost">Save</button>',true);
 const f=$('#costForm',m);f.elements.charge_basis.onchange=()=>{const b=f.elements.charge_basis.value;f.elements.pax.value=['PAYING_PAX','PER_PAX'].includes(b)?v.paying_pax:b==='TOTAL_GUESTS'?v.total_guests:1};
 $('#saveCost',m).onclick=async()=>{if(!f.reportValidity())return;const d=formObj(f);['pax','qty','unit_price'].forEach(k=>d[k]=Number(d[k]));d.supplier_id=preset.supplier_id||null;d.rate_version_id=f.elements.manual?.checked?null:(preset.rate_version_id||null);d.reviewed=!!f.elements.reviewed?.checked;
 try{await api.request(preset.id?'cost-items/'+preset.id:'quote-versions/'+v.id+'/cost-items',{method:preset.id?'PATCH':'POST',body:d});closeModal();toast('Cost saved');await renderQuote()}catch(e){toast(e.message,true)}};
}
function parseCostTSV(text,v){
 const lines=text.trim().split(/\r?\n/).filter(s=>s.trim());if(!lines.length)throw Error('No cost rows');if(lines.length>201)throw Error('One to 200 cost rows required');
 const header=lines[0].split('\t').map(s=>s.trim().toLowerCase());const keys=['service_name','pax','qty','unit_price','currency','category','service_date','notes','charge_basis'];if(header[0]==='service_name')lines.shift();
 return lines.map((line,index)=>{const cells=line.split('\t');if(cells.length>keys.length)throw Error('Too many columns in row '+(index+1));const d=Object.fromEntries(keys.map((k,i)=>[k,(cells[i]||'').trim()]));if(!d.service_name)throw Error('Service required in row '+(index+1));
 d.charge_basis=d.charge_basis||'PAYING_PAX';d.pax=d.pax===''?(['PAYING_PAX','PER_PAX'].includes(d.charge_basis)?Number(v.paying_pax):d.charge_basis==='TOTAL_GUESTS'?Number(v.total_guests):1):Number(d.pax);d.qty=d.qty===''?1:Number(d.qty);d.unit_price=Number(d.unit_price);if(!Number.isFinite(d.pax)||d.pax<=0||!Number.isFinite(d.qty)||d.qty<=0||!Number.isFinite(d.unit_price)||d.unit_price<0)throw Error('Invalid numbers in row '+(index+1));
 d.currency=d.currency||'VND';d.category=d.category||'OTHER';d.service_date=d.service_date||v.start_date;if(!d.notes)throw Error('Review reason required in row '+(index+1));return d});
}
function showCostPaste(v){
 const m=modal('Excel Paste','<p>service_name → pax → qty → unit_price → currency → category → service_date → notes → charge_basis</p><p>Use tab-separated columns and plain decimal numbers (no thousands separators). Blank pax uses the charge basis; blank basis uses Paying Pax. Notes are required.</p><textarea id="costPaste" rows="10"></textarea><button class="btn" id="previewCosts">Preview rows</button><div id="costPreview"></div>','<button class="btn" data-close>Cancel</button><button class="btn primary" id="saveCosts" disabled>Save all rows</button>',true);
 let rows=null;$('#costPaste',m).oninput=()=>{rows=null;$('#saveCosts',m).disabled=true};
 $('#previewCosts',m).onclick=()=>{try{rows=parseCostTSV($('#costPaste',m).value,v);$('#costPreview',m).innerHTML=rows.map(r=>'<p>'+esc(r.service_name)+' · '+r.pax+' × '+r.qty+' × '+money(r.unit_price,r.currency)+' = '+money(r.pax*r.qty*r.unit_price,r.currency)+'</p>').join('');$('#saveCosts',m).disabled=false}catch(e){toast(e.message,true)}};
 $('#saveCosts',m).onclick=async()=>{if(!rows)return;try{await api.request('quote-versions/'+v.id+'/cost-items/bulk',{method:'POST',body:{items:rows}});closeModal();await renderQuote()}catch(e){toast(e.message,true)}};
}
async function showQuoteReuse(v){
 if(PREVIEW)return toast('Use the local or staging API for Clone & Reuse.',true);
 try{const x=await api.request('inquiries');const m=modal('Clone & Reuse','<p>'+rcLabel('Program text needs review; copied rates require current-date review.')+'</p><label>Target inquiry<select id="reuseInquiry">'+x.items.map(i=>'<option value="'+i.id+'">'+esc(i.inquiry_ref)+' · '+esc(i.lead_contact_name||i.title)+' · '+esc(i.start_date)+' · '+esc(i.paying_pax)+' pax</option>').join('')+'</select></label><label><select id="reuseMode"><option value="PROGRAM_ONLY">Program Only</option>'+(can('quote.view_cost')?'<option value="PROGRAM_COST">Program + Cost Structure</option><option value="FULL_DRAFT">Full Quote Draft</option>':'')+'</select></label>','<button class="btn" data-close>Cancel</button><button class="btn primary" id="reuseSave">Create DRAFT clone</button>');
 $('#reuseSave',m).onclick=async()=>{const b=$('#reuseSave',m);b.disabled=true;try{const result=await api.request('quote-versions/'+v.id+'/reuse',{method:'POST',body:{inquiry_id:Number($('#reuseInquiry',m).value),mode:$('#reuseMode',m).value}});closeModal();state.quoteId=result.id;state.quoteStep='info';await renderQuote()}catch(e){toast(e.message,true);b.disabled=false}};
 }catch(e){toast(e.message,true)}
}


async function showRateMatch(v,existing=null){const m=modal('Match Approved Rate',`<form id="rateMatchForm"><div class="form-grid"><div class="field span3"><label>Category</label><select name="category"><option>HOTEL</option><option>TRANSPORT</option><option>GUIDE</option><option>CRUISE</option><option>TOUR</option><option>ATTRACTION</option><option>MEAL</option></select></div><div class="field span3"><label>Destination</label><input name="destination"></div><div class="field span3"><label>Travel Date</label><input type="date" name="travel_date" value="${esc(v.start_date||'')}"></div><div class="field span3"><label>Pax</label><input type="number" name="pax" value="${n(v.total_guests)}"></div></div><button type="button" class="btn primary" id="findRates" style="margin-top:12px">Find Valid Rates</button></form><div id="rateMatches" style="margin-top:16px"></div>`,`<button class="btn" data-close>Close</button>`,true);$('#findRates',m).onclick=async()=>{const d=formObj($('#rateMatchForm',m));try{const x=await api.request(`v3/rate-match?market=${encodeURIComponent(state.quoteData?.trip?.market||'')}&trip_ref=${encodeURIComponent(state.quoteData?.trip?.trip_ref||'')}&category=${encodeURIComponent(d.category)}&destination=${encodeURIComponent(d.destination)}&travel_date=${encodeURIComponent(d.travel_date)}&pax=${encodeURIComponent(d.pax)}`);const box=$('#rateMatches',m);box.innerHTML=(x.items||[]).length?`<div class="table-wrap"><table class="table"><thead><tr><th>Supplier</th><th>Product</th><th>Validity</th><th>Rate</th><th></th></tr></thead><tbody>${x.items.map(r=>`<tr><td>${esc(r.supplier_name)}</td><td><strong>${esc(r.product_name)}</strong><br><span class="muted">${esc(r.option_name||'')}</span></td><td>${fdate(r.valid_from)} → ${fdate(r.valid_to)}</td><td>${money(r.effective_amount??r.amount,r.currency)}<br><span class="muted">${esc(r.rate_basis)}</span></td><td><button class="btn small success" data-use-rate='${esc(JSON.stringify(r))}'>Use Rate</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No approved rate matched this context.</div>';$$('[data-use-rate]',box).forEach(b=>b.onclick=()=>{const r=JSON.parse(b.dataset.useRate);closeModal();showCostForm(v,{...(existing||{}),...r,id:existing?.id,unit_price:r.effective_amount,category:d.category,service_date:d.travel_date,pax:r.rate_basis==='PER_PAX'?n(v.paying_pax):1,qty:1,service_name:r.product_name+(r.option_name?' — '+r.option_name:'')})})}catch(e){toast(e.message,true)}}}
function renderQuotePrice(body,x){const v=x.version,locked=['SENT','CONFIRMED','SUPERSEDED'].includes(v.version_status);body.innerHTML=`<div class="grid2"><div class="panel"><div class="panel-head"><h2>4. Pricing</h2></div><div class="panel-body"><form id="priceForm"><div class="form-grid"><div class="field span4"><label>FX VND / USD</label><input type="number" name="fx_rate" value="${n(v.fx_rate)}" ${locked?'disabled':''}></div><div class="field span4"><label>Pricing Mode</label><select name="pricing_mode" ${locked?'disabled':''}><option value="MARKUP" ${v.pricing_mode==='MARKUP'?'selected':''}>Markup on Cost</option><option value="TARGET_MARGIN" ${v.pricing_mode==='TARGET_MARGIN'?'selected':''}>Target Profit Margin</option><option value="MANUAL" ${v.pricing_mode==='MANUAL'?'selected':''}>Manual Final Price</option></select></div><div class="field span4"><label>Markup / Margin %</label><input type="number" step="0.01" name="pricing_value" value="${n(v.pricing_value)}" ${locked?'disabled':''}></div><div class="field span4"><label>Round Up</label><select name="rounding_step" ${locked?'disabled':''}><option value="0">No Rounding</option><option value="1" ${n(v.rounding_step)===1?'selected':''}>Next USD 1</option><option value="5" ${n(v.rounding_step)===5?'selected':''}>Next USD 5</option><option value="10" ${n(v.rounding_step)===10?'selected':''}>Next USD 10</option></select></div><div class="field span4"><label>Final Selling USD / Pax</label><input type="number" step="0.01" name="selling_per_pax" value="${n(v.selling_per_pax).toFixed(2)}" ${locked?'disabled':''}></div></div></form>${!locked?'<div class="actions"><button class="btn primary" id="savePrice">Recalculate & Save</button></div>':''}</div></div><div class="panel"><div class="panel-head"><h2>Price Health</h2></div><div class="panel-body"><div class="cost-summary"><div class="cost-box"><label>Cost / Paying Pax</label><b>${money(v.cost_per_paying_pax,'USD')}</b></div><div class="cost-box"><label>Selling / Pax</label><b>${money(v.selling_per_pax,'USD')}</b></div><div class="cost-box"><label>Profit</label><b>${money(v.profit_amount,'USD')}</b></div><div class="cost-box"><label>Margin</label><b>${n(v.margin_pct).toFixed(1)}%</b></div></div><div class="check ${n(v.margin_pct)>=12?'ok':'warn'}" style="margin-top:16px">${n(v.margin_pct)>=12?'✓ Healthy margin':'⚠ Margin is below the 12% baseline. Review before approval.'}</div></div></div></div>`;if(!locked)$('#savePrice').onclick=async()=>{const d=formObj($('#priceForm'));['fx_rate','pricing_value','rounding_step','selling_per_pax'].forEach(k=>d[k]=n(d[k]));try{await api.request(`quote-versions/${v.id}`,{method:'PUT',body:d});toast('Pricing recalculated');renderQuote()}catch(e){toast(e.message,true)}}}
function quoteChecks(v,items){const schedule=parseJson(v.schedule_json,[]);return[{ok:!!v.tour_name,label:'Tour name'},{ok:!!v.start_date&&!!v.end_date,label:'Travel dates'},{ok:n(v.total_guests)>0&&n(v.paying_pax)>0,label:'Guest / Paying Pax'},{ok:schedule.length>0,label:'Itinerary schedule'},{ok:items.length>0,label:'Cost items'},{ok:n(v.selling_per_pax)>0,label:'Selling price'},{ok:!!v.included_text,label:'Included services'},{ok:!!v.excluded_text,label:'Excluded services'}]}
function renderQuoteSend(body,x){const v=x.version,q=x.quote,items=x.cost_items||[],checks=quoteChecks(v,items),all=checks.every(c=>c.ok),schedule=parseJson(v.schedule_json,[]);body.innerHTML=`<div class="grid2"><div class="panel"><div class="panel-head"><h2>5. Quality Check & Send</h2></div><div class="panel-body"><div class="checklist">${checks.map(c=>`<div class="check ${c.ok?'ok':'bad'}">${c.ok?'✓':'⛔'} ${esc(c.label)}</div>`).join('')}</div><div class="divider"></div><div class="actions"><button class="btn" id="previewProposal">Review Proposal</button>${v.version_status==='DRAFT'||v.version_status==='READY'?`<button class="btn success" id="approveQuote" ${!all?'disabled':''}>Approve Quote</button>`:''}${v.version_status==='APPROVED'?'<button class="btn primary" id="sendQuote">Send / Lock Version</button>':''}${v.version_status==='SENT'?'<button class="btn success" id="confirmQuote">Customer Confirmed</button><button class="btn" id="newVersion">Create Revision</button>':''}${v.version_status==='CONFIRMED'?'<button class="btn primary" id="createBooking">Create / Open Booking</button>':''}</div></div></div><div class="panel"><div class="panel-head"><h2>Customer-safe Summary</h2></div><div class="panel-body"><h3>${esc(v.tour_name)}</h3><p>${fdate(v.start_date)} → ${fdate(v.end_date)} · ${n(v.total_guests)} Guests · ${esc(v.hotel_level||'')}</p><div class="cost-box"><label>Package Rate</label><b>${money(v.selling_per_pax,'USD')} / Paying Pax</b><span class="muted">Total ${money(v.total_selling,'USD')}</span></div><h3 class="section-title">Short Schedule</h3>${schedule.map((d,i)=>`<p><strong>Day ${i+1}:</strong> ${esc(d.title||'')}</p>`).join('')}</div></div></div>`;$('#previewProposal').onclick=()=>showProposalPreview(x);if($('#approveQuote'))$('#approveQuote').onclick=async()=>{try{await api.request(`quotes/${q.id}/approve`,{method:'POST',body:{}});toast('Quote approved');renderQuote()}catch(e){toast(e.message,true)}};if($('#sendQuote'))$('#sendQuote').onclick=async()=>{const m=modal('Send Quote',`<div class="field"><label>Channel</label><select id="sendChannel"><option>WHATSAPP</option><option>EMAIL</option><option>PDF</option><option>WORD</option><option>COPY_MESSAGE</option></select><span class="help">Sending locks this quote version. Revisions create V${n(v.version_no)+1} instead of overwriting.</span></div>`,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="doSend">Mark Sent & Lock</button>`);$('#doSend',m).onclick=async()=>{try{await api.request(`quotes/${q.id}/send`,{method:'POST',body:{channel:$('#sendChannel',m).value}});closeModal();toast('Quote sent and version locked');renderQuote()}catch(e){toast(e.message,true)}}};if($('#confirmQuote'))$('#confirmQuote').onclick=async()=>{if(!await confirmBox('Confirm Booking','Confirm that the customer accepted this exact quote version?','Confirm'))return;try{await api.request(`quotes/${q.id}/confirm`,{method:'POST',body:{}});toast('Customer confirmation recorded');renderQuote()}catch(e){toast(e.message,true)}};if($('#newVersion'))$('#newVersion').onclick=async()=>{try{await api.request(`quotes/${q.id}/new-version`,{method:'POST',body:{}});toast('New quote revision created');state.quoteStep='info';renderQuote()}catch(e){toast(e.message,true)}};if($('#createBooking'))$('#createBooking').onclick=async()=>{try{const b=await api.request(`quotes/${q.id}/create-booking`,{method:'POST',body:{}});navigate('booking',{bookingId:Number(b.id)})}catch(e){toast(e.message,true)}}}
function showProposalPreview(x){const v=x.version,t=x.trip,schedule=parseJson(v.schedule_json,[]);const html=`<div class="preview-doc" id="proposalDoc"><div style="text-align:right"><strong>Vietnam Travel Advisor</strong></div><h1>${esc(v.tour_name)}</h1><p><strong>${esc(t.lead_contact_name||'Guest')}</strong> · ${fdate(v.start_date)} – ${fdate(v.end_date)} · ${n(v.total_guests)} Guests</p><h2>Journey Summary</h2>${schedule.map((d,i)=>`<div class="day"><strong>Day ${i+1} · ${esc(d.title||'')}</strong><p>${esc(d.description||'').replaceAll('\n','<br>')}</p><small>${esc(d.meals||'')} ${d.overnight?'· Overnight: '+esc(d.overnight):''}</small></div>`).join('')}<h2>Package Rate</h2><p style="font-size:24px"><strong>${money(v.selling_per_pax,'USD')} / Paying Pax</strong></p><h2>Included</h2><p>${esc(v.included_text||'').replaceAll('\n','<br>')}</p><h2>Excluded</h2><p>${esc(v.excluded_text||'').replaceAll('\n','<br>')}</p><h2>Terms</h2><p>${esc(v.terms_text||'').replaceAll('\n','<br>')}</p><p style="margin-top:30px"><strong>Vietnam Travel Advisor</strong><br>#4 Lane 293/2/6 Ngoc Thuy St, Long Bien, Hanoi<br>info@vietnamtraveladvisor.com.vn · WhatsApp +84 582 230 993</p></div>`;const m=modal('Proposal Review — Customer-safe',html,`<button class="btn" data-close>Close</button><button class="btn" id="copyQuote">Copy WhatsApp</button><button class="btn" id="wordQuote">Word-compatible</button><button class="btn primary" id="printQuote">Print / PDF</button>`,true);$('#printQuote',m).onclick=()=>printHtml('VTA Proposal',html);$('#wordQuote',m).onclick=()=>downloadDoc('VTA_Proposal_'+x.quote.quote_ref+'.doc',html);$('#copyQuote',m).onclick=async()=>{const msg=`${v.tour_name}\n${fdate(v.start_date)} - ${fdate(v.end_date)}\n${n(v.total_guests)} Guests\n\nSHORT SCHEDULE\n${schedule.map((d,i)=>`Day ${i+1}: ${d.title||''}`).join('\n')}\n\nPACKAGE RATE\n${money(v.selling_per_pax,'USD')} / Paying Pax\n\nVietnam Travel Advisor`;await navigator.clipboard.writeText(msg);toast('WhatsApp quote copied')}}
function printHtml(title,html){const w=window.open('','_blank');w.document.write(`<html><head><title>${esc(title)}</title><style>body{font-family:Arial,sans-serif;color:#13243a;line-height:1.55;padding:28px}.preview-doc{max-width:900px;margin:auto}h1{font-size:30px}h2{font-size:20px;border-bottom:1px solid #ddd;padding-bottom:6px}.day{margin:14px 0}</style></head><body>${html}</body></html>`);w.document.close();w.focus();setTimeout(()=>w.print(),250)}
function downloadDoc(name,html){const blob=new Blob([`<html><meta charset="utf-8"><body>${html}</body></html>`],{type:'application/msword'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

async function renderBookings(){const x=await api.request('bookings');const w=$('#workspace');w.innerHTML=`<div class="page"><div class="page-head"><div><h1>BOOKINGS</h1><p>Confirmed trips · guests · flights · services · suppliers · finance</p></div></div><div class="toolbar"><button class="btn" data-bfilter="">All</button><button class="btn" data-bfilter="UPCOMING">Upcoming</button><button class="btn" data-bfilter="AT_RISK">At Risk</button><button class="btn" data-bfilter="ON_TOUR">On Tour</button></div><div class="panel"><div class="table-wrap"><table class="table responsive"><thead><tr><th>Booking</th><th>Guest / Trip</th><th>Travel</th><th>Pax</th><th>Operations</th><th>Payment</th><th>Readiness</th><th>Risk</th></tr></thead><tbody>${(x.items||[]).map(b=>`<tr class="clickable" data-open-booking="${b.id}"><td data-label="Booking"><strong>${esc(b.booking_ref)}</strong></td><td data-label="Guest"><strong>${esc(b.lead_guest_name||'')}</strong><br><span class="muted">${esc(b.title||'')}</span></td><td data-label="Travel">${fdate(b.start_date)} → ${fdate(b.end_date)}</td><td data-label="Pax">${n(b.total_guests)}</td><td data-label="Ops">${badge(b.operations_status)}</td><td data-label="Payment">${badge(b.customer_payment_status)}</td><td data-label="Readiness"><strong>${n(b.readiness_pct).toFixed(0)}%</strong><br><span class="muted">${n(b.confirmed_services||0)}/${n(b.service_count||0)} services</span></td><td data-label="Risk">${badge(b.risk_level)}</td></tr>`).join('')}</tbody></table></div></div></div>`;$$('[data-open-booking]').forEach(b=>b.onclick=()=>navigate('booking',{bookingId:Number(b.dataset.openBooking)}));$$('[data-bfilter]').forEach(b=>b.onclick=async()=>{const f=b.dataset.bfilter;const d=await api.request('bookings'+(f?'?filter='+encodeURIComponent(f):''));x.items=d.items;renderBookingsFiltered(d.items||[])})}
function renderBookingsFiltered(items){const tbody=$('.table tbody');if(!tbody)return;tbody.innerHTML=items.map(b=>`<tr class="clickable" data-open-booking="${b.id}"><td data-label="Booking"><strong>${esc(b.booking_ref)}</strong></td><td data-label="Guest"><strong>${esc(b.lead_guest_name||'')}</strong><br><span class="muted">${esc(b.title||'')}</span></td><td data-label="Travel">${fdate(b.start_date)} → ${fdate(b.end_date)}</td><td data-label="Pax">${n(b.total_guests)}</td><td data-label="Ops">${badge(b.operations_status)}</td><td data-label="Payment">${badge(b.customer_payment_status)}</td><td data-label="Readiness">${n(b.readiness_pct).toFixed(0)}%</td><td data-label="Risk">${badge(b.risk_level)}</td></tr>`).join('');$$('[data-open-booking]').forEach(b=>b.onclick=()=>navigate('booking',{bookingId:Number(b.dataset.openBooking)}))}

async function showTravelDocuments(bookingId){try{
 const data=await api.request(`bookings/${bookingId}/travel-documents`),can=p=>api.user.permissions.includes(p);
 const next={DRAFT:['review','Submit for review'],REVIEW:['ready','Mark ready'],READY:['issue','Issue'],ISSUED:['sent','Record as sent']};
 const m=modal('Travel Document Center',`<p>Every issued version is preserved. Changes require a new document version.</p>${can('travel_document.manage')?`<form id="newTravelDocument"><label>Document type<select name="kind">${['TRAVEL_PACK','FULL_ITINERARY','HOTEL_VOUCHER','TRANSFER_VOUCHER','ACTIVITY_VOUCHER','CRUISE_VOUCHER'].map(k=>`<option value="${k}">${k.replaceAll('_',' ')}</option>`).join('')}</select></label><label>Price visibility<select name="visibility"><option value="HIDE_PRICE">Hide all prices</option><option value="PACKAGE_PRICE">Customer package selling price</option></select></label><button class="btn primary">Prepare new version</button></form>`:''}<div>${data.items.map(d=>`<section class="panel"><div class="panel-body"><h3>${esc(d.kind.replaceAll('_',' '))} · V${d.version_no}</h3><p>${badge(d.status)} · ${esc(d.visibility)}</p><a class="btn" target="_blank" rel="noopener" href="api/index.php?route=travel-documents/${d.id}/html">View / Print</a>${can('travel_document.issue')&&next[d.status]?`<button class="btn primary" data-document-action="${next[d.status][0]}" data-document-id="${d.id}">${next[d.status][1]}</button>`:''}</div></section>`).join('')||'<p>No travel document versions yet.</p>'}</div>`,'',true);
 if($('#newTravelDocument',m))$('#newTravelDocument',m).onsubmit=async event=>{event.preventDefault();try{await api.request(`bookings/${bookingId}/travel-documents`,{method:'POST',body:formObj(event.target)});showTravelDocuments(bookingId)}catch(e){toast(e.message,true)}};
 $$('[data-document-action]',m).forEach(button=>button.onclick=async()=>{try{await api.request(`travel-documents/${button.dataset.documentId}/${button.dataset.documentAction}`,{method:'POST',body:{}});showTravelDocuments(bookingId)}catch(e){toast(e.message,true)}});
 }catch(e){toast(e.message,true)}}

function renderPaymentSchedulesV3(body,ledger,bid,currency){
 const panel=document.createElement('section');panel.className='panel';panel.innerHTML=`<div class="panel-body"><h2>Payment Schedule</h2>${can('customer_payment.record')?'<button class="btn" id="addPaymentInstalment">Add instalment</button>':''}${ledger.schedules.filter(s=>s.direction==='AR'&&s.status!=='CANCELLED').map(s=>`<p><strong>${esc(s.label)}</strong> · ${money(s.amount,s.currency)} · Due ${fdate(s.due_date)} · ${badge(s.status)} ${can('customer_payment.record')?`<button class="btn" data-schedule-invoice="${s.id}">Create linked invoice</button>`:''}</p>`).join('')||'<p>No payment instalments scheduled.</p>'}</div>`;body.prepend(panel);
 if($('#addPaymentInstalment'))$('#addPaymentInstalment').onclick=()=>{const m=modal('Add payment instalment',`<form id="scheduleV3"><label>Label<input name="label" required maxlength="190"></label><label>Amount (${esc(currency)})<input type="number" name="amount" step="0.01" min="0.01" required></label><label>Due date<input type="date" name="due_date" required></label><button class="btn primary">Save schedule</button></form>`);$('#scheduleV3',m).onsubmit=async e=>{e.preventDefault();try{await api.request(`bookings/${bid}/payment-schedules`,{method:'POST',body:{items:[formObj(e.target)]}});closeModal();renderBooking()}catch(err){toast(err.message,true)}}};
 $$('[data-schedule-invoice]',panel).forEach(b=>b.onclick=()=>{const m=modal('Invoice scheduled instalment','<form id="scheduledInvoice"><label>Issue date<input type="date" name="issue_date" required></label><p>The invoice uses this instalment’s amount, currency and due date.</p><button class="btn primary">Create commercial invoice draft</button></form>');$('#scheduledInvoice',m).onsubmit=async e=>{e.preventDefault();try{await api.request(`bookings/${bid}/invoices`,{method:'POST',body:{...formObj(e.target),payment_schedule_id:Number(b.dataset.scheduleInvoice),invoice_type:'CUSTOMER_INVOICE'}});closeModal();renderBooking()}catch(err){toast(err.message,true)}}});
}

async function renderBookingFinanceV3(body,x){try{
 const bid=x.booking.id,can=p=>api.user.permissions.includes(p);
 if(!can('finance.view')||!can('customer_ar.view'))return;const epoch=workspaceEpoch;const [ledger,statement,profit]=await Promise.all([api.request(`bookings/${bid}/finance`),api.request(`bookings/${bid}/statement-v3`),can('profit.view')?api.request(`bookings/${bid}/profit-v3`):Promise.resolve(null)]);
 if(epoch!==workspaceEpoch||!body.isConnected||state.bookingId!==bid)return;body.innerHTML=`<div class="toolbar">${can('customer_payment.record')?'<button class="btn" id="ledgerNewInvoice">New invoice</button><button class="btn primary" id="ledgerReceipt">Record bank receipt</button>':''}</div><div class="notice">Commercial/proforma invoices and payment requests are not Vietnamese VAT e-invoices unless separately issued through an authorized e-invoice system.</div>${profit?`<section class="panel"><div class="panel-body"><h2>Booking profitability</h2><p>Expected ${money(profit.expected_profit)} · Forecast ${money(profit.forecast_profit)} · Actual ${profit.actual_profit===null?'Pending cost reconciliation':money(profit.actual_profit)}</p><p>${profit.actual_final?'Actual profit is final.':'Actual profit is provisional until costs, payments and operations are complete.'}</p></div></section>`:''}<section class="panel"><div class="panel-head"><h2>Customer invoices</h2></div><div class="panel-body">${ledger.invoices.map(i=>`<div class="attention"><div style="flex:1"><strong>${esc(i.invoice_ref)}</strong> · ${badge(i.status)}<p>${esc(i.invoice_type)} · ${money(i.total,i.currency)} · Balance ${money(i.balance,i.currency)}</p></div>${i.commercial_document_ref?`<a class="btn" target="_blank" rel="noopener" href="api/index.php?route=invoices/${i.id}/commercial-html">Commercial document</a>`:i.status!=='DRAFT'&&i.status!=='CANCELLED'&&i.invoice_type!=='CUSTOMER_INVOICE'&&can('customer_payment.record')?`<button class="btn" data-commercial-invoice="${i.id}">Issue commercial document</button>`:''}${i.status==='DRAFT'&&can('customer_payment.record')?`<button class="btn" data-issue-invoice="${i.id}">Issue</button>`:`<a class="btn" target="_blank" rel="noopener" href="api/index.php?route=invoices/${i.id}/html">View / Print</a>`}</div>`).join('')||'<p>No invoices.</p>'}</div></section><section class="panel"><div class="panel-head"><h2>Partner statement</h2></div><div class="panel-body"><form id="statementDates"><label>From<input type="date" name="from" value="${esc(statement.from)}" required></label><label>As of<input type="date" name="as_of" value="${esc(statement.as_of)}" required></label><button class="btn">View statement / aging</button></form><div id="statementSummary"></div><h3>Bank receipts</h3>${statement.receipts.map(r=>`<p><strong>${esc(r.receipt_ref)}</strong> · ${money(r.amount,r.currency)} · ${esc(r.payment_date)} · ${esc(r.transaction_reference)} ${can('customer_payment.record')?`<button class="btn" data-allocate-receipt="${r.id}">Allocate to invoices</button>`:''}</p>`).join('')||'<p>No receipts.</p>'}</div></section><section class="panel"><div class="panel-head"><h2>Supplier AP and reconciliation</h2></div><div class="panel-body">${ledger.payables.map(p=>`<section class="attention"><div style="flex:1"><strong>${esc(p.supplier_name)} · ${esc(p.payable_ref)}</strong><p>${esc(p.label)} · Total ${money(p.total_amount,p.currency)} · Balance ${money(p.balance,p.currency)}</p></div>${can('supplier_payment.record')?`<button class="btn" data-reconcile-payable="${p.id}">Reconcile invoice</button><button class="btn" data-pay-supplier="${p.id}">Record payment</button>`:''}</section>`).join('')||'<p>Payables appear after supplier confirmation.</p>'}</div></section>`;
 renderPaymentSchedulesV3(body,ledger,bid,x.booking.selling_currency);
 const renderStatement=s=>{$('#statementSummary').innerHTML=Object.entries(s.currencies).map(([currency,c])=>`<h3>${esc(currency)}</h3><p>Opening ${money(c.opening,currency)} + Invoices ${money(c.invoices,currency)} − Payments ${money(c.payments,currency)} = Closing ${money(c.closing,currency)}</p><p>Unallocated receipts: ${money(c.unallocated_receipts,currency)}</p><p>Current ${money(c.aging.current,currency)} · 1–30 ${money(c.aging['1_30'],currency)} · 31–60 ${money(c.aging['31_60'],currency)} · 61–90 ${money(c.aging['61_90'],currency)} · 90+ ${money(c.aging['90_plus'],currency)}</p>`).join('')||'<p>No posted entries.</p>'};renderStatement(statement);
 $('#statementDates').onsubmit=async e=>{e.preventDefault();try{renderStatement(await api.request(`bookings/${bid}/statement-v3&`+new URLSearchParams(formObj(e.target))))}catch(error){toast(error.message,true)}};
 $$('[data-issue-invoice]').forEach(b=>b.onclick=async()=>{try{await api.request(`invoices/${b.dataset.issueInvoice}/issue`,{method:'POST',body:{}});renderBooking()}catch(e){toast(e.message,true)}});
 $$('[data-commercial-invoice]').forEach(b=>b.onclick=()=>{const m=modal('Issue commercial document','<form id="commercialDocument"><p>This creates a commercial document for the existing receivable. The proforma and payment allocations remain unchanged.</p><label>Issue date<input name="issue_date" type="date" required></label><button class="btn primary">Issue commercial document</button></form>');$('#commercialDocument',m).onsubmit=async e=>{e.preventDefault();try{await api.request(`invoices/${b.dataset.commercialInvoice}/commercial`,{method:'POST',body:formObj(e.target)});closeModal();renderBooking()}catch(err){toast(err.message,true)}}});
 if($('#ledgerNewInvoice'))$('#ledgerNewInvoice').onclick=()=>{const m=modal('Create invoice instalment',`<form id="invoiceV3"><label>Invoice type<select name="invoice_type"><option value="CUSTOMER_INVOICE">Commercial invoice</option><option value="PROFORMA">Proforma</option><option value="DEPOSIT_REQUEST">Deposit request</option><option value="PAYMENT_REQUEST">Payment request</option><option value="FINAL_REQUEST">Final request</option></select></label><label>Amount (${esc(x.booking.selling_currency)})<input name="subtotal" type="number" min="0.01" step="0.01" required></label><label>Issue date<input type="date" name="issue_date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Due date<input type="date" name="due_date" required></label><p>Each invoice covers a distinct instalment. Existing invoices count toward the booking value.</p><button class="btn primary">Create draft invoice</button></form>`);$('#invoiceV3',m).onsubmit=async e=>{e.preventDefault();try{await api.request(`bookings/${bid}/invoices`,{method:'POST',body:formObj(e.target)});closeModal();renderBooking()}catch(error){toast(error.message,true)}}};
 if($('#ledgerReceipt'))$('#ledgerReceipt').onclick=()=>{const key=crypto.randomUUID();const m=modal('Record one bank receipt',`<form id="receiptV3"><label>Amount (${esc(x.booking.selling_currency)})<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Payment date<input type="date" name="payment_date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Bank transaction reference<input name="transaction_reference" required maxlength="190"></label><button class="btn primary">Record receipt</button></form>`);$('#receiptV3',m).onsubmit=async e=>{e.preventDefault();try{await api.request(`bookings/${bid}/receipts`,{method:'POST',body:{...formObj(e.target),idempotency_key:key}});closeModal();renderBooking()}catch(error){toast(error.message,true)}}};
 $$('[data-allocate-receipt]').forEach(button=>button.onclick=()=>{const r=statement.receipts.find(r=>String(r.id)===button.dataset.allocateReceipt),invoices=statement.outstanding.filter(i=>i.currency===r.currency),key=crypto.randomUUID();const m=modal('Allocate receipt '+r.receipt_ref,`<form id="allocateV3"><label>Allocation date<input type="date" name="allocation_date" value="${new Date().toISOString().slice(0,10)}" required></label>${invoices.map(i=>`<label>${esc(i.invoice_ref)} · ${esc(i.booking_ref)} · Balance ${money(i.balance,i.currency)}<input type="number" data-invoice-allocation="${i.invoice_id}" min="0" step="0.01" value="0"></label>`).join('')||'<p>No outstanding invoices in this currency.</p>'}<button class="btn primary">Allocate payment</button></form>`);$('#allocateV3',m).onsubmit=async e=>{e.preventDefault();const items=$$('[data-invoice-allocation]',m).filter(i=>Number(i.value)>0).map(i=>({invoice_id:Number(i.dataset.invoiceAllocation),amount:i.value}));try{await api.request(`receipts/${r.id}/allocate`,{method:'POST',body:{request_key:key,allocation_date:formObj(e.target).allocation_date,items}});closeModal();renderBooking()}catch(error){toast(error.message,true)}}});
 $$('[data-reconcile-payable]').forEach(button=>button.onclick=()=>{const p=ledger.payables.find(p=>String(p.id)===button.dataset.reconcilePayable);const m=modal('Reconcile supplier invoice',`<form id="supplierInvoiceV3"><p>Confirmed payable ${money(p.total_amount,p.currency)}</p><label>Supplier invoice number<input name="supplier_invoice_no" required></label><label>Invoice amount<input name="invoice_amount" type="number" min="0" step="0.01" value="${n(p.total_amount)}" required></label><label>Review reason<textarea name="reason" required></textarea></label><button class="btn">Submit for review</button></form><div id="reconciliationResult"></div>`);$('#supplierInvoiceV3',m).onsubmit=async e=>{e.preventDefault();try{const r=await api.request(`payables/${p.id}/reconcile`,{method:'POST',body:formObj(e.target)});$('#reconciliationResult',m).innerHTML=`<p>${badge(r.status)} · Variance ${money(r.variance||0,p.currency)}</p>${can('finance.close')&&r.status==='REVIEW_REQUIRED'?'<button class="btn primary" id="approveSupplierInvoice">Approve reconciled invoice</button>':''}`;if($('#approveSupplierInvoice',m))$('#approveSupplierInvoice',m).onclick=async()=>{try{await api.request(`supplier-reconciliations/${r.id}/approve`,{method:'POST',body:{}});closeModal();renderBooking()}catch(error){toast(error.message,true)}}}catch(error){toast(error.message,true)}}});
 $$('[data-pay-supplier]').forEach(button=>button.onclick=()=>{const p=ledger.payables.find(p=>String(p.id)===button.dataset.paySupplier),key=crypto.randomUUID();const m=modal('Record supplier bank payment',`<form id="supplierPaymentV3"><label>Amount (${esc(p.currency)})<input name="amount" type="number" min="0.01" step="0.01" max="${n(p.balance)}" value="${n(p.balance)}" required></label><label>Payment date<input type="date" name="payment_date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Bank transaction reference<input name="transaction_reference" required></label><button class="btn primary">Record payment</button></form>`);$('#supplierPaymentV3',m).onsubmit=async e=>{e.preventDefault();try{await api.request(`payables/${p.id}/payments`,{method:'POST',body:{...formObj(e.target),idempotency_key:key}});closeModal();renderBooking()}catch(error){toast(error.message,true)}}});
 }catch(e){body.innerHTML=`<div class="notice">${esc(e.message)}</div>`;toast(e.message,true)}}

async function renderBooking(){if(!state.bookingId)return navigate('bookings');const epoch=workspaceEpoch,id=state.bookingId;const x=await api.request(`bookings/${id}`);if(epoch!==workspaceEpoch||state.bookingId!==id||$('#workspace')?.dataset.view!=='booking')return;state.bookingData=x;const b=x.booking,t=x.trip,tabs=['overview','guests','flights','services','suppliers','documents',...(can('finance.view')&&can('customer_ar.view')?['finance']:[]),'activity'],tab=tabs.includes(state.bookingTab)?state.bookingTab:'overview';const w=$('#workspace');w.innerHTML=`<div class="page"><div class="record-header"><div class="record-top"><div><div class="record-ref">${esc(b.booking_ref)}</div><div class="record-title">${esc(b.lead_guest_name||t.title||'Master Booking')}</div><div class="record-meta"><span>${fdate(b.start_date)} → ${fdate(b.end_date)}</span><span>${n(b.total_guests)} Guests</span><span>${n(b.paying_pax)} Paying</span><span>${n(b.foc)} FOC</span><span>${esc(t.market||'')}</span></div></div><div class="record-status">${badge(b.operations_status)}${badge(b.customer_payment_status)}${badge(b.risk_level)}<button class="btn" id="bookingBack">← Bookings</button></div></div></div><div class="tabs">${tabs.map(x=>`<button data-booking-tab="${x}" class="${tab===x?'active':''}">${x.toUpperCase()}</button>`).join('')}</div><div id="bookingBody"></div></div>`;$('#bookingBack').onclick=()=>navigate('bookings');$$('[data-booking-tab]').forEach(btn=>btn.onclick=()=>{state.bookingTab=btn.dataset.bookingTab;renderBooking()});const body=$('#bookingBody');if(api.user.permissions.includes('travel_document.view')){const docButton=document.createElement('button');docButton.className='btn';docButton.textContent='Travel Document Center';docButton.onclick=()=>showTravelDocuments(b.id);body.before(docButton);}if(tab==='overview')renderBookingOverview(body,x);if(tab==='guests')renderBookingGuests(body,x);if(tab==='flights')renderBookingFlights(body,x);if(tab==='services')renderBookingServices(body,x);if(tab==='suppliers')renderBookingSuppliers(body,x);if(tab==='documents')renderBookingDocuments(body,x);if(tab==='finance')renderBookingFinanceV3(body,x);if(tab==='activity')renderBookingActivity(body,x)}
function renderBookingOverview(body,x){const b=x.booking,f=x.finance||{},services=x.services||[],missing=services.filter(s=>!['CONFIRMED','COMPLETED','CANCELLED'].includes(s.booking_status));body.innerHTML=`<div class="kpis"><div class="kpi"><div class="label">Departure Readiness</div><div class="value">${n(b.readiness_pct).toFixed(0)}%</div><div class="sub">${badge(b.risk_level)}</div></div><div class="kpi"><div class="label">Services</div><div class="value">${services.length}</div><div class="sub">${services.filter(s=>['CONFIRMED','COMPLETED'].includes(s.booking_status)).length} confirmed</div></div><div class="kpi"><div class="label">Customer Balance</div><div class="value">${money(f.customer_balance||0,b.selling_currency||'USD')}</div><div class="sub">${badge(b.customer_payment_status)}</div></div><div class="kpi"><div class="label">Forecast Profit</div><div class="value">${can('profit.view')?money(f.forecast_profit||0,'USD'):'Restricted'}</div><div class="sub">Expected ${can('profit.view')?money(f.expected_profit||0,'USD'):'—'}</div></div></div><div class="grid2"><div class="panel"><div class="panel-head"><h2>Trip Control</h2></div><div class="panel-body"><div class="form-grid"><div class="field span6"><label>Lead Guest</label><div><strong>${esc(b.lead_guest_name||'—')}</strong><br><span class="muted">${esc(b.lead_whatsapp||'')} ${esc(b.lead_email||'')}</span></div></div><div class="field span6"><label>Travel</label><div>${fdate(b.start_date)} → ${fdate(b.end_date)}<br><span class="muted">${daysBetween(b.start_date,b.end_date)} days</span></div></div><div class="field span6"><label>Guest Count</label><div>${n(b.total_guests)} total · ${n(b.paying_pax)} paying · ${n(b.foc)} FOC</div></div><div class="field span6"><label>Confirmed Selling</label><div>${money(b.confirmed_selling,b.selling_currency||'USD')}</div></div><div class="field span12"><label>Client Promises / Special Requests</label><div class="codeish">${esc(b.client_promises||b.special_requests||'No special notes recorded.')}</div></div></div></div></div><div class="panel"><div class="panel-head"><h2>Needs Attention</h2></div><div class="panel-body">${missing.length?missing.slice(0,8).map(s=>`<div class="attention ${['HOTEL','TRANSPORT','GUIDE','CRUISE'].includes(s.category)?'high':''}"><div class="dot"></div><div><strong>${esc(s.service_name)}</strong><div class="meta">${fdate(s.service_date)} · ${esc(s.category)} · ${esc(s.booking_status)}</div></div></div>`).join(''):'<div class="empty"><strong>Operationally controlled</strong>No open services require attention.</div>'}</div></div></div>`}
function renderBookingGuests(body,x){const items=x.guests||[];body.innerHTML=`<div class="toolbar"><button class="btn primary" id="addGuest">+ Passenger</button><span class="help">Passport data is collected only when operationally required.</span></div><div class="panel"><div class="table-wrap"><table class="table responsive"><thead><tr><th>Guest</th><th>Type</th><th>Nationality</th><th>WhatsApp</th><th>Dietary / Needs</th><th>Room</th></tr></thead><tbody>${items.map(g=>`<tr><td data-label="Guest"><strong>${esc(g.full_name)}</strong>${g.passport_number?`<br><span class="muted">Passport ${esc(g.passport_number)}</span>`:''}</td><td data-label="Type">${badge(g.guest_type)}</td><td data-label="Nationality">${esc(g.nationality||'—')}</td><td data-label="WhatsApp">${esc(g.whatsapp||'—')}</td><td data-label="Dietary">${esc(g.dietary||g.special_needs||'—')}</td><td data-label="Room">${esc(g.room_preference||'—')}</td></tr>`).join('')}</tbody></table></div></div>`;$('#addGuest').onclick=()=>showGuestForm(x.booking)}
function showGuestForm(bkg){const m=modal('Add Passenger',`<form id="guestForm"><div class="form-grid"><div class="field span6"><label>Full Name</label><input name="full_name" required></div><div class="field span3"><label>Type</label><select name="guest_type"><option>ADULT</option><option>CHILD</option><option>INFANT</option><option>FOC</option></select></div><div class="field span3"><label>Nationality</label><input name="nationality"></div><div class="field span6"><label>WhatsApp</label><input name="whatsapp"></div><div class="field span6"><label>Email</label><input name="email" type="email"></div><div class="field span4"><label>Passport Number</label><input name="passport_number"></div><div class="field span4"><label>Passport Expiry</label><input type="date" name="passport_expiry"></div><div class="field span4"><label>Passport Country</label><input name="passport_country"></div><div class="field span4"><label>Dietary</label><input name="dietary" placeholder="Vegetarian / Jain / Halal..."></div><div class="field span4"><label>Room Preference</label><input name="room_preference"></div><div class="field span4"><label>Special Needs</label><input name="special_needs"></div></div></form>`,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="saveGuest">Add Passenger</button>`);$('#saveGuest',m).onclick=async()=>{const f=$('#guestForm',m);if(!f.reportValidity())return;try{await api.request(`bookings/${bkg.id}/guests`,{method:'POST',body:formObj(f)});closeModal();toast('Passenger added');renderBooking()}catch(e){toast(e.message,true)}}}
function renderBookingFlights(body,x){const items=x.flights||[];body.innerHTML=`<div class="toolbar"><button class="btn primary" id="addFlight">+ Flight Sector</button></div><div class="panel"><div class="table-wrap"><table class="table responsive"><thead><tr><th>Date</th><th>Flight</th><th>Route</th><th>Departure</th><th>Arrival</th><th>Terminal</th><th>Status</th></tr></thead><tbody>${items.map(f=>`<tr><td data-label="Date">${fdate(f.flight_date)}</td><td data-label="Flight"><strong>${esc(f.flight_number)}</strong><br><span class="muted">${esc(f.airline||'')}</span></td><td data-label="Route">${esc(f.origin_code||'')} → ${esc(f.destination_code||'')}</td><td data-label="Departure">${esc(f.departure_time||'—')}</td><td data-label="Arrival">${esc(f.arrival_time||'—')}</td><td data-label="Terminal">${esc(f.terminal||'—')}</td><td data-label="Status">${badge(f.status)}</td></tr>`).join('')}</tbody></table></div></div>`;$('#addFlight').onclick=()=>showFlightForm(x.booking)}
